/**
 * test_bank_dig.js — Digitalización Aplicada a los Sectores Productivos (DIG)
 * 5 Unidades × 42 preguntas = 210 preguntas
 * 2º DAW — Banco de preguntas oficial
 */
const TEST_BANK_DIG = [

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 1 — Introducción a la Transformación Digital y THD
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dig_u1_q1", unit:1, question:"¿Cuál es la diferencia fundamental entre 'Digitalización' (Digitization) y 'Transformación Digital' (Digital Transformation)?", options:["Son sinónimos en el ámbito empresarial, concepto diferente al que se describe en esta pregunta","Digitalización es convertir información analógica a formato digital","La transformación digital solo aplica a la banca","La digitalización requiere inteligencia artificial obligatoriamente"], correct:1, explanation:"La digitalización transforma formatos; la transformación digital transforma la estrategia de la empresa, la cultura humana y los procesos para generar nuevo valor.", noShuffle:false },
  { concept_id:"dig_u1_q2", unit:1, question:"¿Qué significan las siglas THD en el contexto de la economía productiva moderna?", options:["Terminales de Hardware Digital, concepto diferente al que se describe en esta pregunta","Tecnologías Habilitadoras Digitales (Key Enabling Technologies)","Técnicas de Hiper-Despliegue, concepto diferente al que se describe en esta pregunta","Tratamiento de Hiper-Datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las THD son tecnologías de alto impacto (IA, IoT, Blockchain, Cloud, 5G) que catalizan la innovación y competitividad de los sectores industriales.", noShuffle:false },
  { concept_id:"dig_u1_q3", unit:1, question:"¿Qué hito tecnológico y organizativo define la llamada 'Cuarta Revolución Industrial' (Industria 4.0)?", options:["La máquina de vapor, concepto que se aplica en un contexto distinto","La producción en masa y la electricidad, concepto diferente al que se describe en esta pregunta","La informática y los ordenadores personales (Tercera Revolución)","La convergencia de sistemas ciberfísicos, Internet de las Cosas (IoT)"], correct:3, explanation:"La Industria 4.0 conecta máquinas, sensores y sistemas de información en fábricas inteligentes autónomas y auto-optimizables.", noShuffle:false },
  { concept_id:"dig_u1_q4", unit:1, question:"¿Qué es el IoT (Internet de las Cosas - Internet of Things)?", options:["Navegar por internet desde el televisor, concepto diferente al que se describe en esta pregunta","La red de objetos físicos (sensores, maquinaria, vehículos","Un tipo de cable de fibra óptica, concepto diferente al que se describe en esta pregunta","Un protocolo de correo electrónico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"IoT permite monitorizar el estado de activos físicos en remoto y automatizar respuestas sin intervención humana directa.", noShuffle:false },
  { concept_id:"dig_u1_q5", unit:1, question:"¿Cuáles son las '5 V' fundamentales que caracterizan al fenómeno del Big Data?", options:["Venta, Venta, Valor, Venta y Variedad","Volumen, Velocidad, Variedad, Veracidad y Valor","Voz, Vídeo, Ventas, Vector y Virtual","Visibilidad, Vínculo, Volumen, Versión y Validez"], correct:1, explanation:"Big Data aborda inmensos Volúmenes de datos generados a gran Velocidad, con Variedad de formatos (estructurados y no estructurados), asegurando su Veracidad para extraer Valor real de negocio.", noShuffle:false },
  { concept_id:"dig_u1_q6", unit:1, question:"¿Qué diferencia fundamental hay entre Inteligencia Artificial (IA), Machine Learning (ML) y Deep Learning (DL)?", options:["Son exactamente lo mismo, concepto diferente al que se describe en esta pregunta","La IA es el campo global que busca imitar la inteligencia humana","Deep Learning es más antiguo que la IA, concepto diferente al que se describe en esta pregunta","Machine Learning no utiliza datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es una relación de conjuntos concéntricos: IA contiene a ML, y ML contiene a DL.", noShuffle:false },
  { concept_id:"dig_u1_q7", unit:1, question:"¿Qué es la tecnología Blockchain (Cadena de Bloques)?", options:["Un tipo de disco duro cifrado, concepto diferente al que se describe en esta pregunta","Un libro de contabilidad distribuido (DLT), inmutable y descentralizado donde las transacciones se agrupan en bloques enlazados criptográficamente garantizando la confianza sin intermediarios centrales","Un virus informático, concepto diferente al que se describe en esta pregunta","Una base de datos de Microsoft Access, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Blockchain asegura la trazabilidad, autenticidad y no repudio de registros compartidos entre partes no confiables.", noShuffle:false },
  { concept_id:"dig_u1_q8", unit:1, question:"¿Qué es un 'Smart Contract' (Contrato Inteligente)?", options:["Un contrato laboral en formato PDF, que pertenece a un ambito distinto del aqui estudiado","Un programa informático autoejecutable almacenado en una blockchain que ejecuta y liquida acuerdos automáticamente cuando se cumplen condiciones preprogramadas específicas","Un contrato firmado con certificado digital, que pertenece a un ambito distinto del aqui estudiado","Un formulario web interactivo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Elimina intermediarios legales o financieros ejecutando reglas deterministas (ej: liberar un pago si un sensor IoT confirma la recepción de mercancía).", noShuffle:false },
  { concept_id:"dig_u1_q9", unit:1, question:"¿Qué es la Robótica Colaborativa (Cobots) en la industria digitalizada?", options:["Robots de películas de ficción, concepto diferente al que se describe en esta pregunta","Robots diseñados expresamente con sensores de proximidad para trabajar de forma segura codo con codo junto a operarios humanos sin necesidad de jaulas o barreras de aislamiento físico","Software de chat en páginas web, concepto diferente al que se describe en esta pregunta","Brazos mecánicos tradicionales de soldadura, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los cobots asumen tareas repetitivas o ergonómicamente pesadas complementando las destrezas complejas de los trabajadores humanos.", noShuffle:false },
  { concept_id:"dig_u1_q10", unit:1, question:"¿Qué ventaja diferencial aporta la tecnología móvil 5G a los entornos industriales y productivos frente al 4G?", options:["Que los teléfonos son más caros, concepto diferente al que se describe en esta pregunta","Velocidad de gigabits, latencia ultra-baja (submilisegundos) y capacidad masiva para conectar hasta un millón de dispositivos IoT por kilómetro cuadrado (mMTC)","No necesita antenas, concepto diferente al que se describe en esta pregunta","Usa cables telefónicos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La baja latencia del 5G hace viable el control remoto en tiempo real de maquinaria crítica, vehículos autónomos y cirugía teleasistida.", noShuffle:false },
  { concept_id:"dig_u1_q11", unit:1, question:"¿Qué es la Realidad Aumentada (AR) frente a la Realidad Virtual (VR)?", options:["Son sinónimos, concepto diferente al que se describe en esta pregunta","La Realidad Aumentada superpone información y elementos gráficos digitales sobre el entorno real en tiempo real; la Realidad Virtual aísla completamente al usuario sumergiéndolo en un entorno 100% digital","La AR requiere casco cerrado obligatorio, concepto diferente al que se describe en esta pregunta","La VR no admite interacción, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La AR es clave en mantenimiento industrial para mostrar guías técnicas flotantes mientras el técnico repara una máquina real.", noShuffle:false },
  { concept_id:"dig_u1_q12", unit:1, question:"¿Qué es un 'Gemelo Digital' (Digital Twin)?", options:["Un clon biológico del operador, concepto diferente al que se describe en esta pregunta","Una réplica virtual digital de alta fidelidad de un objeto","Una copia de seguridad de archivos en dos discos","Un segundo ordenador idéntico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite anticipar averías de turbinas, optimizar cadenas de montaje completas o simular obras civiles antes de que ocurran fallos en el mundo real.", noShuffle:false },
  { concept_id:"dig_u1_q13", unit:1, question:"¿Qué es el Mantenimiento Predictivo habilitado por IA e IoT frente al mantenimiento preventivo tradicional?", options:["Esperar a que la máquina se rompa para arreglarla (correctivo) es una accion que no define correctamente este concepto","Analizar patrones continuos de vibración, temperatura y acústica para predecir con exactitud cuándo va a fallar un componente y sustituirlo justo antes de la rotura, sin paradas innecesarias","Cambiar piezas cada 3 meses por calendario fijo (preventivo), concepto diferente al que se describe en esta pregunta","Pintar las máquinas periódicamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El mantenimiento predictivo maximiza la vida útil de los componentes y evita costosas paradas no programadas en fábricas.", noShuffle:false },
  { concept_id:"dig_u1_q14", unit:1, question:"¿Qué es el RPA (Robotic Process Automation)?", options:["Robots humanoides que limpian oficinas, concepto diferente al que se describe en esta pregunta","Software de automatización (bots de software) que imita las interacciones repetitivas de humanos en interfaces de usuario para procesar formularios, facturas y transferir datos entre sistemas heredados","Un tipo de lenguaje ensamblador, concepto diferente al que se describe en esta pregunta","Un motor de videojuegos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"RPA agiliza tareas administrativas de 'cortar y pegar' entre aplicaciones heterogéneas sin necesidad de desarrollar complejas integraciones de APIs.", noShuffle:false },
  { concept_id:"dig_u1_q15", unit:1, question:"¿Qué es la Fabricación Aditiva?", options:["Sumar números en una hoja de cálculo, concepto diferente al que se describe en esta pregunta","La producción de piezas tridimensionales capa sobre capa a partir de modelos digitales (impresión 3D), en contraposición a los métodos sustractivos tradicionales (mecanizado, corte)","El ensamblaje manual en cadena, concepto diferente al que se describe en esta pregunta","La fundición en moldes tradicionales, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite prototipado ultrarrápido, geometrías complejas imposibles de fresar y fabricación personalizada de repuestos bajo demanda.", noShuffle:false },
  { concept_id:"dig_u1_q16", unit:1, question:"¿Qué barrera principal citan frecuentemente las organizaciones como el mayor obstáculo en la Transformación Digital?", options:["La falta de ordenadores en el mercado, concepto que se aplica en un contexto distinto","La resistencia cultural al cambio de los empleados y la falta de liderazgo y capacitación en competencias digitales, por encima de las limitaciones tecnológicas","El precio del papel, que puede confundirse con este termino en contabilidad general","La velocidad del ratón, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La tecnología se compra; la cultura organizativa y la gestión del cambio humano requieren visión estratégica y pedagogía constante.", noShuffle:false },
  { concept_id:"dig_u1_q17", unit:1, question:"¿Qué es la 'Economía de Plataformas' (Platform Economy)?", options:["Vender plataformas de madera es una accion que no define correctamente este concepto","Modelos de negocio digitales que crean valor facilitando intercambios y conexiones directas entre grupos de usuarios interdependientes gracias a los efectos de red","La venta de software físico, concepto que se aplica en un contexto distinto","Un sistema operativo, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Las plataformas escalan con costes marginales cercanos a cero y basan su poder en intermediar datos y transacciones.", noShuffle:false },
  { concept_id:"dig_u1_q18", unit:1, question:"¿Qué es el 'Efecto de Red' (Network Effect) en modelos de negocio digitales?", options:["La velocidad de la conexión WiFi, concepto que se aplica en un contexto distinto","Un fenómeno donde el valor de un producto, servicio o plataforma aumenta exponencialmente para cada usuario a medida que se incorporan más usuarios a la misma red","La caída de los servidores por saturación, concepto que se aplica en un contexto distinto","El cableado entre ordenadores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Explica por qué plataformas como WhatsApp o LinkedIn son tan difíciles de desbancar una vez alcanzan masa crítica.", noShuffle:false },
  { concept_id:"dig_u1_q19", unit:1, question:"¿Qué es el término 'Data-Driven Organization' (Organización Guiada por Datos)?", options:["Una empresa que tiene muchos discos duros, concepto diferente al que se describe en esta pregunta","Una empresa cuya cultura y procesos se basan en la recopilación","Una empresa que vende bases de datos, concepto diferente al que se describe en esta pregunta","Un fabricante de sensores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sustituye el criterio 'HiPPO' (Highest Paid Person's Opinion) por experimentos contrastados y analítica predictiva.", noShuffle:false },
  { concept_id:"dig_u1_q20", unit:1, question:"¿Qué es el 'Servitización' en la industria digitalizada?", options:["Contratar más camareros, concepto diferente al que se describe en esta pregunta","La transición de un modelo de venta tradicional de producto físico hacia un modelo de suscripción o pago por servicio continuo basado en el uso y resultados garantizados","La venta de servidores en la nube, concepto que se aplica en un contexto distinto","Un tipo de contrato de telecomunicaciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Convierte ingresos transaccionales aislados en flujos de ingresos recurrentes apoyados en la monitorización IoT del producto.", noShuffle:false },
  { concept_id:"dig_u1_q21", unit:1, question:"¿Qué es el 'Business Intelligence' (BI) frente a la analítica predictiva?", options:["Son sinónimos, concepto diferente al que se describe en esta pregunta","El BI analiza datos históricos para responder a '¿Qué ocurrió y por qué?' (informes, cuadros de mando/dashboards); la analítica predictiva utiliza modelos estadísticos e IA para anticipar '¿Qué ocurrirá en el futuro?'","BI solo sirve para finanzas, concepto diferente al que se describe en esta pregunta","El BI no utiliza gráficos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"BI ayuda a comprender el retrovisor del negocio; la analítica predictiva e IA proyecta el parabrisas hacia adelante.", noShuffle:false },
  { concept_id:"dig_u1_q22", unit:1, question:"¿Qué papel desempeñan los 'Dashboards' o cuadros de mando visuales en la gestión digital?", options:["Ocupar espacio en las pantallas, concepto diferente al que se describe en esta pregunta","Sintetizar los Indicadores Clave de Rendimiento (KPIs) en tiempo real mediante gráficos interactivos intuitivos para facilitar la toma de decisiones ágiles","Cifrar las bases de datos, concepto diferente al que se describe en esta pregunta","Instalar programas en el servidor es una accion que no define correctamente este concepto"], correct:1, explanation:"Herramientas como Power BI, Tableau o Grafana democratizan el acceso al dato dentro de la empresa.", noShuffle:false },
  { concept_id:"dig_u1_q23", unit:1, question:"¿Qué es la IA Generativa (GenAI) y qué herramientas lideran su adopción empresarial?", options:["Un software que genera contraseñas seguras, que aunque es una herramienta util, no corresponde a esta definicion","Modelos fundacionales de inteligencia artificial (LLMs y modelos de difusión) capaces de generar texto, código, imágenes y contenido multimedia nuevo y contextualizado","Un antivirus de última generación, concepto diferente al que se describe en esta pregunta","Un compilador de código fuente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Está transformando la productividad en desarrollo de software, atención al cliente, redacción técnica y diseño.", noShuffle:false },
  { concept_id:"dig_u1_q24", unit:1, question:"¿Qué es el 'Prompt Engineering' en la interacción con modelos de IA?", options:["La ingeniería de reparación de hardware, concepto que se aplica en un contexto distinto","La técnica de diseñar, estructurar y formular instrucciones precisas y contextuales para que un modelo de lenguaje (LLM) genere la respuesta óptima y deseada","Un tipo de cable de red, concepto diferente al que se describe en esta pregunta","La instalación de servidores, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Permite exprimir las capacidades de los LLMs mediante técnicas como Few-Shot Prompting, Chain-of-Thought y Role Prompting.", noShuffle:false },
  { concept_id:"dig_u1_q25", unit:1, question:"¿Qué es el RAG (Retrieval-Augmented Generation) en soluciones empresariales de IA?", options:["Un protocolo de red antiguo, concepto diferente al que se describe en esta pregunta","Una arquitectura que combina un LLM con una base de datos vectorial de documentos corporativos privados para que la IA responda citando fuentes reales actualizadas sin alucinar","Un compresor de imágenes, concepto diferente al que se describe en esta pregunta","Un algoritmo de ordenación, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita alucinaciones y permite a la IA consultar manuales internos confidenciales de la empresa sin tener que reentrenar el modelo fundacional.", noShuffle:false },
  { concept_id:"dig_u1_q26", unit:1, question:"¿Qué es la 'Brecha Digital' (Digital Divide)?", options:["Una avería física en un cable submarino, concepto diferente al que se describe en esta pregunta","La desigualdad económica, social y formativa en el acceso","La diferencia de velocidad entre dos procesadores","Un fallo de ciberseguridad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Mitigar la brecha digital es clave para la cohesión social y la inclusión de colectivos vulnerables o mayores.", noShuffle:false },
  { concept_id:"dig_u1_q27", unit:1, question:"¿Qué marco europeo de referencia define y clasifica las Competencias Digitales de los ciudadanos?", options:["DigComp (Digital Competence Framework for Citizens)","ISO 9001, concepto diferente al que se describe en esta pregunta","Scrum Guide, concepto diferente al que se describe en esta pregunta","ITIL v4, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"DigComp identifica 21 competencias divididas en 5 áreas: información, comunicación, creación de contenido, seguridad y resolución de problemas.", noShuffle:false },
  { concept_id:"dig_u1_q28", unit:1, question:"¿Qué es el 'Reskilling' y el 'Upskilling' del capital humano en la era digital?", options:["Despedir y contratar nuevo personal, concepto diferente al que se describe en esta pregunta","Upskilling es mejorar las habilidades del empleado para optimizar su puesto actual; Reskilling es capacitarlo en competencias completamente nuevas para desempeñar un puesto digital diferente","Técnicas de descanso laboral, concepto diferente al que se describe en esta pregunta","Un tipo de nómina, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Estrategias indispensables para adaptar la plantilla a la automatización sin destruir puestos de trabajo.", noShuffle:false },
  { concept_id:"dig_u1_q29", unit:1, question:"¿Qué es el 'Customer Experience' (CX) en la estrategia digital de una empresa?", options:["La experiencia del programador, concepto diferente al que se describe en esta pregunta","La percepción holística acumulada que tiene un cliente sobre la marca a lo largo de todos sus puntos de contacto digitales y físicos durante todo su ciclo de vida","El coste del producto, que puede confundirse con este termino en contabilidad general","La calidad de la conexión a internet, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Un CX excelente fomenta la fidelización, el boca a boca positivo y el valor de vida del cliente (LTV).", noShuffle:false },
  { concept_id:"dig_u1_q30", unit:1, question:"¿Qué es la 'Omnicanalidad' frente a la multicanalidad?", options:["Tener un solo canal de venta, concepto diferente al que se describe en esta pregunta","La multicanalidad ofrece varios canales aislados; la omnicanalidad integra y sincroniza todos los canales (tienda física, web, app, redes sociales, teléfono) de forma continua sin fricción para el usuario","Vender solo por redes sociales es una accion que no define correctamente este concepto","Un canal de televisión digital, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite al cliente empezar la compra en el móvil, probar el producto en tienda física y finalizar el pago en la web sin perder el contexto.", noShuffle:false },
  { concept_id:"dig_u1_q31", unit:1, question:"¿Qué es un CRM (Customer Relationship Management)?", options:["Un tipo de base de datos relacional, concepto diferente al que se describe en esta pregunta","Un sistema de software empresarial que centraliza todas las interacciones","Un servidor de correo electrónico, concepto diferente al que se describe en esta pregunta","Un protocolo de red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Plataformas como Salesforce o HubSpot gestionan el embudo de ventas y optimizan la atención al cliente.", noShuffle:false },
  { concept_id:"dig_u1_q32", unit:1, question:"¿Qué es un ERP (Enterprise Resource Planning)?", options:["Un lenguaje de programación, concepto diferente al que se describe en esta pregunta","Un sistema de gestión integral que unifica y coordina los procesos clave de la empresa en una base de datos centralizada: finanzas, inventarios, compras, recursos humanos y producción","Un programa de facturación básica, que aunque es una herramienta util, no corresponde a esta definicion","Un editor de texto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sistemas como SAP u Odoo integran todos los departamentos para que la información fluya sin silos aislados.", noShuffle:false },
  { concept_id:"dig_u1_q33", unit:1, question:"¿Qué es la 'Interoperabilidad' entre sistemas digitales en un ecosistema productivo?", options:["Que los ordenadores sean de la misma marca, concepto diferente al que se describe en esta pregunta","La capacidad de sistemas de información, dispositivos y aplicaciones heterogéneas para intercambiar datos de forma automática e interpretar esa información con precisión semántica compartida","Que funcionen con Windows únicamente, concepto diferente al que se describe en esta pregunta","Tener la misma contraseña, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se apoya en estándares abiertos (como APIs REST, formatos JSON/XML y modelos de datos normalizados).", noShuffle:false },
  { concept_id:"dig_u1_q34", unit:1, question:"¿Qué papel juegan las APIs (Application Programming Interfaces) en la economía digital moderna?", options:["Son códigos secretos de piratas, concepto diferente al que se describe en esta pregunta","Actúan como los 'conectores universales' que permiten a diferentes aplicaciones y empresas comunicar datos y servicios de forma segura, modular y automatizada","Son cables de comunicación física, concepto diferente al que se describe en esta pregunta","Son manuales en papel, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La 'API Economy' permite a empresas monetizar sus capacidades y crear alianzas integradas (ej: pagos de Stripe en Shopify).", noShuffle:false },
  { concept_id:"dig_u1_q35", unit:1, question:"¿Qué es el 'Low-Code' y 'No-Code' en el desarrollo de soluciones empresariales?", options:["Programar con lenguaje ensamblador, concepto diferente al que se describe en esta pregunta","Plataformas que permiten a usuarios o desarrolladores crear aplicaciones","No usar ordenadores para programar, concepto diferente al que se describe en esta pregunta","Software con errores de código, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Acelera la digitalización permitiendo a los 'Citizen Developers' de departamentos de negocio resolver necesidades internas sin esperar a TI.", noShuffle:false },
  { concept_id:"dig_u1_q36", unit:1, question:"¿Qué es el 'Shadow IT' (TI en la Sombra) en una organización?", options:["Hackers ocultos en el sótano, concepto diferente al que se describe en esta pregunta","El uso de aplicaciones, servicios cloud o dispositivos por parte de los empleados para trabajar sin la aprobación ni el control del departamento de TI","Servidores apagados por la noche, concepto diferente al que se describe en esta pregunta","Un virus de espionaje, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Nace de la necesidad de agilidad de los empleados ante la lentitud de TI, pero introduce graves riesgos de fuga de datos y vulnerabilidades normativas.", noShuffle:false },
  { concept_id:"dig_u1_q37", unit:1, question:"¿Qué es la 'Desintermediación' provocada por la digitalización?", options:["Despedir a los jefes, concepto diferente al que se describe en esta pregunta","La eliminación de intermediarios tradicionales en la cadena de valor (distribuidores, agencias, brokers) conectando directamente al productor con el consumidor final (D2C - Direct to Consumer)","Eliminar los cables de red, concepto diferente al que se describe en esta pregunta","Un fallo de comunicación, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Reduce costes y traslada más margen a los productores mejorando los precios finales para los usuarios.", noShuffle:false },
  { concept_id:"dig_u1_q38", unit:1, question:"¿Qué es el 'Time to Market' (TTM) y por qué se reduce con la digitalización?", options:["La hora de apertura del mercado, que puede confundirse con este termino en contabilidad general","El tiempo que transcurre desde que se concibe una idea de producto hasta que está disponible para la venta a los clientes finales; la digitalización lo reduce mediante metodologías ágiles y CI/CD","El tiempo de respuesta del servidor, aunque este indicador se calcula de forma diferente","La duración de una reunión, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Lanzar productos con rapidez permite validar hipótesis en el mercado real antes de que los competidores reaccionen.", noShuffle:false },
  { concept_id:"dig_u1_q39", unit:1, question:"¿Qué es el 'Open Innovation' (Innovación Abierta) formulado por Henry Chesbrough?", options:["Publicar todo el código en internet gratis, concepto diferente al que se describe en esta pregunta","Un modelo de gestión de la innovación donde las empresas combinan ideas internas con colaboraciones externas (startups, universidades, clientes, competidores) para acelerar el desarrollo","Innovar solo dentro del laboratorio de la empresa, concepto diferente al que se describe en esta pregunta","Copiar a la competencia, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Reconoce que no todos los expertos más brillantes del mundo trabajan para tu propia compañía.", noShuffle:false },
  { concept_id:"dig_u1_q40", unit:1, question:"¿Qué es una 'Startup' frente a una PYME tradicional?", options:["Una empresa que no gana dinero, concepto diferente al que se describe en esta pregunta","Una organización temporal diseñada para buscar un modelo de negocio repetible, altamente escalable y exponencial, operando en condiciones de extrema incertidumbre tecnológica","Una empresa con menos de 10 trabajadores, concepto diferente al que se describe en esta pregunta","Un negocio de hostelería, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"A diferencia de una PYME que busca estabilidad y beneficios locales, la startup busca hipercrecimiento global apalancada en tecnología.", noShuffle:false },
  { concept_id:"dig_u1_q41", unit:1, question:"¿Qué es el 'Modelo Canvas' (Business Model Canvas) de Alexander Osterwalder?", options:["Un software de dibujo digital, que aunque es una herramienta util, no corresponde a esta definicion","Una plantilla de gestión estratégica visual que resume los 9 bloques fundamentales de un modelo de negocio en un solo lienzo (propuesta de valor, clientes, canales, ingresos, costes...)","Un tipo de pantalla táctil, concepto diferente al que se describe en esta pregunta","Una base de datos de marketing, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite debatir, iterar y pivotar modelos de negocio ágilmente en equipo.", noShuffle:false },
  { concept_id:"dig_u1_q42", unit:1, question:"¿Qué es la 'Economía Circular' impulsada por tecnologías digitales?", options:["Una economía que solo usa monedas redondas, concepto diferente al que se describe en esta pregunta","Un modelo de producción y consumo que busca eliminar residuos y contaminación mediante el diseño, manteniendo productos y materiales en uso continuo al mayor valor posible (reducir, reutilizar, reciclar)","La venta de productos en círculos, concepto que se aplica en un contexto distinto","Un tipo de gráfico financiero, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las tecnologías IoT y pasaportes digitales de producto permiten rastrear materiales para su reutilización y reacondicionamiento continuo.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 2 — Cloud Computing, Modelos SaaS y Arquitecturas Digitales
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dig_u2_q1", unit:2, question:"¿Qué es el modelo de pago por uso (Pay-as-you-go) en servicios Cloud?", options:["Pagar una cuota fija anual obligatoria, concepto diferente al que se describe en esta pregunta","Un modelo de tarificación flexible donde la empresa solo paga por la cantidad exacta de recursos computacionales, almacenamiento y ancho de banda consumidos por segundo o minuto","Pagar solo si hay beneficios comerciales, concepto diferente al que se describe en esta pregunta","Un servicio gratuito, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Transforma grandes inversiones de capital previo (CapEx) en gastos operativos predecibles y proporcionales a la actividad (OpEx).", noShuffle:false },
  { concept_id:"dig_u2_q2", unit:2, question:"¿Cuál es la diferencia fundamental entre CapEx y OpEx en la adopción de tecnologías digitales?", options:["CapEx es para software y OpEx para hardware, concepto diferente al que se describe en esta pregunta","CapEx (Capital Expenditure) son gastos de capital en compra de activos físicos propios (servidores, datacenters); OpEx (Operational Expenditure) son costes operativos recurrentes por el consumo de servicios externos (cloud, licencias)","OpEx es más caro siempre, concepto diferente al que se describe en esta pregunta","No tienen relación financiera, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El Cloud permite a las startups arrancar con cero CapEx, escalando su OpEx solo cuando crecen los clientes.", noShuffle:false },
  { concept_id:"dig_u2_q3", unit:2, question:"¿Qué es el modelo de servicio SaaS (Software as a Service)?", options:["Alquilar cables de red, concepto diferente al que se describe en esta pregunta","Un modelo de distribución de software donde una aplicación completa se aloja centralmente en la nube y se accede a través del navegador web o app mediante suscripción periódica","Comprar un CD-ROM de software es una accion que no define correctamente este concepto","Programar en lenguaje C, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El usuario se desentiende de parches, servidores, copias de seguridad o mantenimiento del sistema operativo.", noShuffle:false },
  { concept_id:"dig_u2_q4", unit:2, question:"¿Qué es el modelo PaaS (Platform as a Service) y a quién va dirigido prioritariamente?", options:["A usuarios finales para ver películas, concepto diferente al que se describe en esta pregunta","A equipos de desarrollo de software: proporciona un entorno completo de ejecución, bases de datos y herramientas de despliegue donde solo gestionan su código fuente sin administrar servidores subyacentes","A administradores de redes físicas exclusivamente, concepto diferente al que se describe en esta pregunta","A técnicos de hardware, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Plataformas como Heroku, Google App Engine o AWS Elastic Beanstalk aceleran los lanzamientos de software.", noShuffle:false },
  { concept_id:"dig_u2_q5", unit:2, question:"¿Qué es el modelo IaaS (Infrastructure as a Service)?", options:["Una suite ofimática en la nube, concepto diferente al que se describe en esta pregunta","El aprovisionamiento bajo demanda de recursos informáticos fundamentales: servidores virtuales, almacenamiento en disco, redes y cortafuegos virtuales donde el cliente instala y gestiona el sistema operativo y las aplicaciones","Un servicio de diseño gráfico, concepto diferente al que se describe en esta pregunta","Un antivirus, concepto que no se corresponde con la definicion correcta"], correct:1, explanation:"AWS EC2, Google Compute Engine y Azure Virtual Machines son los referentes mundiales de IaaS.", noShuffle:false },
  { concept_id:"dig_u2_q6", unit:2, question:"¿Qué es una estrategia 'Multi-Cloud' en una empresa?", options:["Tener varios monitores en el escritorio, concepto diferente al que se describe en esta pregunta","Utilizar intencionadamente los servicios de dos o más proveedores de nube pública distintos, mejorar negociación y aprovechar fortalezas especializadas","Tener varias redes WiFi, concepto diferente al que se describe en esta pregunta","Desplegar solo en servidores locales, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Aumenta la resiliencia pero añade complejidad de gestión e interoperabilidad.", noShuffle:false },
  { concept_id:"dig_u2_q7", unit:2, question:"¿Qué es la 'Elasticidad' en cloud computing?", options:["Hacer cables flexibles es una accion que no define correctamente este concepto","La capacidad de aprovisionar o desaprovisionar dinámicamente recursos de computación de forma automática para adaptarse a los picos y valles de demanda en tiempo real sin intervención humana","Servidores hechos de goma, concepto diferente al que se describe en esta pregunta","La velocidad de conexión, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Garantiza que una tienda online no caiga en Black Friday y no pague de más durante la madrugada.", noShuffle:false },
  { concept_id:"dig_u2_q8", unit:2, question:"¿Qué es el 'Edge Computing' en el procesamiento de datos industriales?", options:["Procesar datos en centros de datos centrales, concepto diferente al que se describe en esta pregunta","Procesar y analizar los datos de sensores localmente cerca de donde se originan (en la propia fábrica o dispositivo) para obtener respuestas instantáneas sin la latencia de viajar a la nube","Guardar datos en discos externos, concepto diferente al que se describe en esta pregunta","Desactivar la conexión a internet, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Crítico en robótica o vehículos autónomos donde esperar 100ms de ida y vuelta a la nube causaría accidentes.", noShuffle:false },
  { concept_id:"dig_u2_q9", unit:2, question:"¿Qué son las '6 R' de la migración al Cloud según AWS?", options:["Seis colores de servidores, concepto diferente al que se describe en esta pregunta","Estrategias de migración de aplicaciones: Rehost (Lift and Shift)","Seis lenguajes de programación, concepto diferente al que se describe en esta pregunta","Seis cables de red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Guían la decisión de si mover una aplicación tal cual, actualizar su plataforma o reescribirla como nativa en la nube.", noShuffle:false },
  { concept_id:"dig_u2_q10", unit:2, question:"¿En qué consiste la estrategia de migración al Cloud 'Rehost' o 'Lift-and-Shift'?", options:["Reescribir la aplicación en microservicios, concepto diferente al que se describe en esta pregunta","Mover una aplicación y sus máquinas virtuales del centro de datos local a la nube prácticamente sin realizar cambios en su arquitectura o código","Comprar una solución SaaS nueva es una accion que no define correctamente este concepto","Apagar la aplicación, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es la vía más rápida y con menor riesgo inicial de migración, aunque no aprovecha todas las ventajas nativas del cloud.", noShuffle:false },
  { concept_id:"dig_u2_q11", unit:2, question:"¿En qué consiste la estrategia de migración 'Refactor' o 'Re-architect'?", options:["Copiar archivos por FTP, concepto diferente al que se describe en esta pregunta","Rediseñar y reescribir la aplicación para aprovechar capacidades nativas de la nube como microservicios, serverless y bases de datos gestionadas","Cambiar la contraseña del administrador, concepto diferente al que se describe en esta pregunta","Dejar la aplicación en local, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Exige mayor inversión y tiempo pero maximiza la escalabilidad, resiliencia y eficiencia de costes a largo plazo.", noShuffle:false },
  { concept_id:"dig_u2_q12", unit:2, question:"¿Qué es el 'Cloud-Native' (Nativo de la Nube)?", options:["Un ordenador fabricado en la nube, concepto diferente al que se describe en esta pregunta","Un enfoque para crear y ejecutar aplicaciones diseñado expresamente para explotar el modelo de computación cloud, basado en contenedores, microservicios, mallas de servicios, APIs declarativas e infraestructura inmutable","Un software sin conexión, que aunque es una herramienta util, no corresponde a esta definicion","Una aplicación de escritorio, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a las organizaciones realizar cambios de alto impacto con frecuencia, predictibilidad y mínimo esfuerzo.", noShuffle:false },
  { concept_id:"dig_u2_q13", unit:2, question:"¿Qué es la CNCF (Cloud Native Computing Foundation)?", options:["Una empresa privada de hosting, concepto diferente al que se describe en esta pregunta","Una organización sin ánimo de lucro adscrita a la Linux Foundation que alberga y fomenta proyectos abiertos líderes como Kubernetes, Prometheus, Envoy y Helm","Un tribunal de arbitraje de patentes, concepto diferente al que se describe en esta pregunta","Un fabricante de routers, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Establece los estándares tecnológicos neutrales sobre los que se apoya la arquitectura cloud moderna.", noShuffle:false },
  { concept_id:"dig_u2_q14", unit:2, question:"¿Qué es la 'Soberanía del Dato' (Data Sovereignty) en almacenamiento cloud?", options:["Que los datos pertenezcan al rey, concepto diferente al que se describe en esta pregunta","El concepto legal de que los datos digitales están sujetos a las leyes y estructuras de gobernanza del país o jurisdicción física en el que se encuentran almacenados y procesados","Que los datos no se puedan borrar, concepto diferente al que se describe en esta pregunta","Que el usuario sea el dueño de la empresa, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Exige a empresas europeas almacenar datos en centros de datos ubicados en la UE para cumplir con el RGPD y evitar leyes extraterritoriales como la CLOUD Act de EE.UU.", noShuffle:false },
  { concept_id:"dig_u2_q15", unit:2, question:"¿Qué es la iniciativa europea 'Gaia-X'?", options:["Una nueva moneda digital, concepto diferente al que se describe en esta pregunta","Un proyecto impulsado por empresas e instituciones europeas para crear una infraestructura de datos federada, segura y transparente que garantice la soberanía digital de Europa frente a gigantes cloud estadounidenses y asiáticos","Una red social europea, concepto diferente al que se describe en esta pregunta","Un cable transatlántico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Establece reglas comunes e interoperables de compartición de datos bajo estándares y valores éticos de la Unión Europea.", noShuffle:false },
  { concept_id:"dig_u2_q16", unit:2, question:"¿Qué es la arquitectura 'Serverless' en el ecosistema cloud?", options:["No usar servidores físicos en el mundo, concepto diferente al que se describe en esta pregunta","Un modelo donde el proveedor gestiona íntegramente la asignación de máquinas, escalando de cero a miles de ejecuciones de forma transparente y cobrando únicamente por el tiempo exacto de CPU consumido por petición","Tener servidores gratuitos, concepto diferente al que se describe en esta pregunta","Programar sin base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Elimina la necesidad de aprovisionar o pagar por servidores ociosos esperando tráfico.", noShuffle:false },
  { concept_id:"dig_u2_q17", unit:2, question:"¿Qué es un 'BaaS' (Backend as a Service) como Firebase o Supabase?", options:["Una copia de seguridad de audio, concepto diferente al que se describe en esta pregunta","Plataformas que proporcionan servicios de backend preconstruidos y gestionados (autenticación, base de datos en tiempo real, almacenamiento de archivos, notificaciones push) mediante SDKs directos para frontend y móvil","Un servidor físico de alquiler, concepto diferente al que se describe en esta pregunta","Un tipo de cable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a desarrolladores frontend construir aplicaciones móviles y web completas sin necesidad de programar un servidor propio desde cero.", noShuffle:false },
  { concept_id:"dig_u2_q18", unit:2, question:"¿Qué es la 'Latencia' en comunicaciones de red cloud y por qué es crucial?", options:["El tamaño del archivo en bytes, concepto diferente al que se describe en esta pregunta","El tiempo que tarda un paquete de datos en viajar desde el origen hasta el destino; una latencia alta provoca retrasos perceptibles y degrada la experiencia de usuario y el rendimiento de las aplicaciones","El número de ordenadores conectados, concepto que se aplica en un contexto distinto","La fecha de creación del servidor, aunque este indicador se calcula de forma diferente"], correct:1, explanation:"Crucial en trading de alta frecuencia, videojuegos online, telemedicina y consultas continuas a bases de datos distribuidas.", noShuffle:false },
  { concept_id:"dig_u2_q19", unit:2, question:"¿Qué es una CDN (Content Delivery Network) en la optimización de aplicaciones digitales?", options:["Un canal de televisión digital, concepto diferente al que se describe en esta pregunta","Una red de servidores proxy distribuidos geográficamente en puntos de presencia (PoPs) mundiales que cachean y sirven contenido cerca de los usuarios reduciendo la latencia de descarga","Una red de bases de datos relacionales, concepto diferente al que se describe en esta pregunta","Un proveedor de fibra óptica, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Alivia la carga del servidor de origen y acelera la carga de imágenes, scripts y assets multimedia a nivel global.", noShuffle:false },
  { concept_id:"dig_u2_q20", unit:2, question:"¿Qué es la 'Conmutación por Error' (Failover) en alta disponibilidad cloud?", options:["Un fallo que apaga todo el sistema, concepto diferente al que se describe en esta pregunta","El cambio automático y transparente hacia un sistema o servidor redundante de respaldo cuando el componente principal sufre una avería o caída de servicio","Una alarma de incendio, concepto diferente al que se describe en esta pregunta","Un reinicio manual del servidor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Garantiza la continuidad del negocio sin que los clientes perciban la caída del nodo maestro.", noShuffle:false },
  { concept_id:"dig_u2_q21", unit:2, question:"¿Qué es el 'Multi-Tenant' (Multi-Inquilino) en la arquitectura de aplicaciones SaaS?", options:["Tener varios propietarios de la empresa, concepto diferente al que se describe en esta pregunta","Una arquitectura de software donde una única instancia de la aplicación y base de datos sirve a múltiples clientes (inquilinos) de forma compartida, manteniendo sus datos estrictamente aislados y privados mediante software","Tener varias oficinas físicas, concepto diferente al que se describe en esta pregunta","Un software instalado en varios PCs, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Permite al proveedor de SaaS actualizar y mantener una única plataforma para millones de usuarios con economías de escala masivas.", noShuffle:false },
  { concept_id:"dig_u2_q22", unit:2, question:"¿Qué es el 'Single-Tenant' frente al Multi-Tenant?", options:["Un software para una sola persona, que aunque es una herramienta util, no corresponde a esta definicion","Una arquitectura donde cada cliente dispone de una instancia de software y base de datos completamente aislada y dedicada en exclusiva en su propio entorno de hardware o nube privada","Un software sin base de datos, que aunque es una herramienta util, no corresponde a esta definicion","Una licencia gratuita, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Exigido a menudo por clientes corporativos o banca por requisitos estrictos de seguridad, cumplimiento y personalización profunda.", noShuffle:false },
  { concept_id:"dig_u2_q23", unit:2, question:"¿Qué es el 'API Gateway' en una arquitectura de microservicios cloud?", options:["La puerta física del centro de datos, concepto diferente al que se describe en esta pregunta","Un único punto de entrada unificado que recibe todas las peticiones del exterior, enrutándolas a los microservicios correspondientes y gestionando autenticación, limitación de tasa (rate limiting), CORS y monitorización","Un cable de red seguro, concepto diferente al que se describe en esta pregunta","Un módem de internet, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Desacopla a los clientes externos de la topología interna cambiante de los microservicios.", noShuffle:false },
  { concept_id:"dig_u2_q24", unit:2, question:"¿Qué es la 'Orquestación de Contenedores' en la nube?", options:["Una banda de música digital, concepto diferente al que se describe en esta pregunta","La gestión automatizada del ciclo de vida, despliegue, escalado dinámico","El empaquetado de archivos en zip, concepto que se aplica en un contexto distinto","Un antivirus para Docker, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sin orquestadores sería inmanejable coordinar manualmente la infraestructura de microservicios moderna.", noShuffle:false },
  { concept_id:"dig_u2_q25", unit:2, question:"¿Qué significa el término 'Cloud Bursting'?", options:["La caída de los servidores por tormentas, concepto que se aplica en un contexto distinto","Una configuración de nube híbrida donde las cargas de trabajo se ejecutan normalmente en servidores locales privados pero 'desbordan' automáticamente a la nube pública cuando la demanda supera la capacidad local","Un ataque de hackers a la nube, concepto diferente al que se describe en esta pregunta","La pérdida de datos en la nube, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Permite absorber picos estacionales de tráfico sin necesidad de sobredimensionar la inversión en hardware físico local.", noShuffle:false },
  { concept_id:"dig_u2_q26", unit:2, question:"¿Qué es el almacenamiento 'Glacier' o almacenamiento frío (Cold Storage) en la nube?", options:["Servidores guardados en el Polo Norte, concepto diferente al que se describe en esta pregunta","Un tipo de almacenamiento de datos ultra-económico diseñado para archivos de retención a largo plazo y copias de seguridad a las que rara vez se accede, con tiempos de recuperación de minutos u horas","Un disco duro congelado, concepto diferente al que se describe en esta pregunta","Una base de datos rápida, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ideal para cumplimiento legal de custodia de registros fiscales durante años con un coste de céntimos por gigabyte.", noShuffle:false },
  { concept_id:"dig_u2_q27", unit:2, question:"¿Qué es la 'Malla de Servicios' (Service Mesh) como Istio o Linkerd?", options:["Una red de cables físicos, concepto diferente al que se describe en esta pregunta","Una capa de infraestructura dedicada que gestiona la comunicación segura entre microservicios (comunicación este-oeste), implementando mTLS, telemetría y enrutamiento inteligente sin modificar el código de la aplicación","Una base de datos de grafos, concepto diferente al que se describe en esta pregunta","Un cortafuegos perimetral, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Añade un proxy sidecar junto a cada contenedor para controlar el tráfico interno con visibilidad total.", noShuffle:false },
  { concept_id:"dig_u2_q28", unit:2, question:"¿Qué es la 'Burbuja de Costes' (Cloud Bill Shock) en finanzas digitales y cómo se previene?", options:["Un fallo en la factura del teléfono, concepto diferente al que se describe en esta pregunta","El sobrecoste inesperado e inasumible en la factura de la nube derivado de recursos mal configurados, bucles descontrolados o ataques; se previene con alertas de presupuesto, cuotas máximas y prácticas FinOps","Un descuento del proveedor, concepto diferente al que se describe en esta pregunta","Pagar por adelantado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Configurar alertas tempranas de facturación (Billing Alerts) en AWS o Azure es la primera medida de seguridad en cualquier proyecto cloud.", noShuffle:false },
  { concept_id:"dig_u2_q29", unit:2, question:"¿Qué es el 'Downtime' no planificado en la gestión de servicios digitales?", options:["El tiempo de descanso del personal, aunque este indicador se calcula de forma diferente","El periodo de tiempo durante el cual un sistema, servicio web o aplicación no está disponible ni operativo para los usuarios debido a fallos o incidencias técnicas imprevistas","El tiempo de mantenimiento programado de noche, aunque este indicador se calcula de forma diferente","El tiempo de arranque de la máquina, aunque este indicador se calcula de forma diferente"], correct:1, explanation:"El downtime no planificado genera pérdidas económicas directas y un daño severo a la reputación corporativa.", noShuffle:false },
  { concept_id:"dig_u2_q30", unit:2, question:"¿Qué diferencia hay entre una base de datos SQL gestionada (ej: AWS RDS) y una base de datos NoSQL gestionada (ej: DynamoDB, MongoDB Atlas)?", options:["SQL no funciona en la nube, concepto diferente al que se describe en esta pregunta","SQL sigue un esquema relacional estructurado estricto con garantías ACID","NoSQL es más antigua que SQL, concepto diferente al que se describe en esta pregunta","SQL no admite transacciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite elegir la tecnología óptima según si priman transacciones relacionales complejas o velocidad de escritura escalable masiva.", noShuffle:false },
  { concept_id:"dig_u2_q31", unit:2, question:"¿Qué es la 'Disponibilidad de Cuatro Nueves' (99.99%)?", options:["Tener 9999 clientes, concepto diferente al que se describe en esta pregunta","Un estándar de alta disponibilidad que garantiza que el sistema no superará más de 52 minutos y 36 segundos de inactividad total acumulada a lo largo de todo un año","Un precio de suscripción, concepto diferente al que se describe en esta pregunta","Un certificado de software, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Exige redundancia en múltiples centros de datos físicos independientes y conmutación automática por error.", noShuffle:false },
  { concept_id:"dig_u2_q32", unit:2, question:"¿Qué es el protocolo AMQP o MQTT en arquitecturas de mensajería digital?", options:["Protocolos de correo electrónico, concepto diferente al que se describe en esta pregunta","Protocolos ligeros de mensajería para colas de trabajo (AMQP en RabbitMQ) o comunicación entre sensores IoT con recursos y ancho de banda muy limitados (MQTT)","Protocolos de transferencia de vídeo, concepto diferente al que se describe en esta pregunta","Estándares de CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permiten enviar telemetría de miles de sensores remotos hacia la nube de forma sumamente eficiente y compacta.", noShuffle:false },
  { concept_id:"dig_u2_q33", unit:2, question:"¿Qué es la gobernanza cloud (Cloud Governance)?", options:["El gobierno del país administrando la nube","El marco de reglas corporativas, políticas de cumplimiento","Un software de auditoría, que aunque es una herramienta util, no corresponde a esta definicion","El contrato de compra, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Previene el descontrol de recursos, gastos desmesurados y brechas de seguridad por configuraciones descuidadas.", noShuffle:false },
  { concept_id:"dig_u2_q34", unit:2, question:"¿Qué es el 'Chaos Engineering' en arquitecturas en la nube?", options:["Hackear servidores de la competencia, concepto diferente al que se describe en esta pregunta","Provocar deliberadamente fallos e interrupciones controladas en entornos productivos para comprobar experimentalmente que el sistema es resiliente y se recupera de forma automática","Escribir código sucio, concepto diferente al que se describe en esta pregunta","Un ataque de ransomware, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite ganar confianza en que la caída de una zona o servidor no afectará a los usuarios finales.", noShuffle:false },
  { concept_id:"dig_u2_q35", unit:2, question:"¿Qué es una 'Landing Zone' en una estrategia de migración al cloud?", options:["La pista de aterrizaje de drones, concepto que se aplica en un contexto distinto","Un entorno cloud bien estructurado, securizado y con múltiples cuentas preconfiguradas que cumple con los estándares de seguridad corporativos antes de desplegar las primeras aplicaciones","Una página de ventas, concepto diferente al que se describe en esta pregunta","Un servidor físico en la oficina, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Proporciona la base de redes, identidades y políticas para comenzar a operar en la nube de forma segura y escalable.", noShuffle:false },
  { concept_id:"dig_u2_q36", unit:2, question:"¿Qué es el 'Zero Trust' en la arquitectura de seguridad de servicios en la nube?", options:["No confiar en ningún empleado, concepto diferente al que se describe en esta pregunta","Un modelo de ciberseguridad que asume que la red interna ya está comprometida; por tanto, 'nunca confía, siempre verifica' explícitamente cada petición, usuario y dispositivo independientemente de su ubicación","Bloquear todas las conexiones, concepto diferente al que se describe en esta pregunta","No usar contraseñas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Supera el modelo caduco de 'seguridad perimetral de castillo' donde todo lo que estaba dentro de la oficina era confiable.", noShuffle:false },
  { concept_id:"dig_u2_q37", unit:2, question:"¿Qué es un 'Broker de Mensajes' (Message Broker) como Apache Kafka?", options:["Un inversor de bolsa digital, concepto diferente al que se describe en esta pregunta","Una plataforma distribuida de streaming de eventos de alto rendimiento capaz de ingerir, procesar y almacenar millones de eventos por segundo en tiempo real de forma tolerante a fallos","Un gestor de correos electrónicos, concepto diferente al que se describe en esta pregunta","Un servidor web de ficheros, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es la columna vertebral para arquitecturas reactivas dirigidas por eventos (Event-Driven Architecture) a escala masiva.", noShuffle:false },
  { concept_id:"dig_u2_q38", unit:2, question:"¿Qué ventaja ofrece el uso de contenedores frente a imágenes completas de VMs en la nube?", options:["Ocupan gigabytes de espacio, concepto diferente al que se describe en esta pregunta","Arranque instantáneo en milisegundos, menor consumo de recursos","No requieren sistema operativo host, concepto diferente al que se describe en esta pregunta","Son inmunes a virus, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Facilita el escalado elástico rápido levantando réplicas en segundos en lugar de minutos.", noShuffle:false },
  { concept_id:"dig_u2_q39", unit:2, question:"¿Qué es el 'Cloud Security Posture Management' (CSPM)?", options:["Una postura ergonómica para trabajar, concepto diferente al que se describe en esta pregunta","Herramientas automatizadas que escanean continuamente la configuración de la nube para identificar riesgos de seguridad, desajustes normativos y políticas permisivas antes de que sean explotadas","Un firewall físico, concepto diferente al que se describe en esta pregunta","Un antivirus local, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Detecta de inmediato si un bucket de S3 con datos confidenciales ha sido expuesto accidentalmente a internet.", noShuffle:false },
  { concept_id:"dig_u2_q40", unit:2, question:"¿Qué es el 'Lock-in de Datos' en servicios SaaS?", options:["Cifrar los datos con clave segura, concepto diferente al que se describe en esta pregunta","La dificultad o coste desorbitado de exportar y migrar tus propios datos desde una plataforma SaaS cerrada debido a formatos propietarios o APIs de exportación limitadas","Un backup automático, concepto diferente al que se describe en esta pregunta","La pérdida de la contraseña, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Exige evaluar siempre la política y facilidad de exportación de datos antes de contratar cualquier solución SaaS estratégica.", noShuffle:false },
  { concept_id:"dig_u2_q41", unit:2, question:"¿Qué es la 'Virtualización de Funciones de Red' (NFV)?", options:["Cables virtuales en 3D, concepto diferente al que se describe en esta pregunta","Sustituir dispositivos de red físicos dedicados (enrutadores, cortafuegos","Un switch de fibra óptica, concepto diferente al que se describe en esta pregunta","Un router doméstico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Reduce enormemente los costes de infraestructura y permite actualizar la red mediante software de forma ágil.", noShuffle:false },
  { concept_id:"dig_u2_q42", unit:2, question:"¿Qué es el 'Auto-Healing' (Autoreparación) en clústeres cloud modernos?", options:["Un software médico, que aunque es una herramienta util, no corresponde a esta definicion","La capacidad de los orquestadores (como Kubernetes) para detectar automáticamente contenedores o nodos que han dejado de responder y reemplazarlos o reiniciarlos de inmediato sin intervención humana","Un antivirus automático, concepto diferente al que se describe en esta pregunta","Un desfragmentador de disco, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Garantiza la resiliencia continua manteniendo siempre activo el número deseado de réplicas en producción.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 3 — Ciberseguridad, Privacidad y Marco Regulatorio (RGPD)
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dig_u3_q1", unit:3, question:"¿Qué es el RGPD (Reglamento General de Protección de Datos de la UE)?", options:["Una ley para cobrar impuestos en internet, concepto diferente al que se describe en esta pregunta","El reglamento europeo (Reglamento UE 2016/679) que unifica y regula el tratamiento y la libre circulación de datos personales, garantizando los derechos y la privacidad de los ciudadanos en la UE","Un estándar técnico de cortafuegos, concepto diferente al que se describe en esta pregunta","Una ley sobre el comercio electrónico de bienes físicos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es de aplicación directa en todos los Estados miembros y establece un marco sancionador muy estricto con multas millonarias.", noShuffle:false },
  { concept_id:"dig_u3_q2", unit:3, question:"¿Qué ley española transpone y complementa el RGPD a nivel nacional garantizando los derechos digitales?", options:["LOPDGDD (Ley Orgánica 3/2018 de Protección de Datos Personales y garantía de los derechos digitales)","Código Penal, concepto diferente al que se describe en esta pregunta","Ley de Enjuiciamiento Civil, concepto diferente al que se describe en esta pregunta","Ley de Propiedad Intelectual, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"La LOPDGDD adapta el derecho español al RGPD e introduce los derechos digitales de los ciudadanos y trabajadores.", noShuffle:false },
  { concept_id:"dig_u3_q3", unit:3, question:"¿Qué se considera un 'Dato Personal' según el RGPD?", options:["Solo el número de cuenta bancaria, concepto diferente al que se describe en esta pregunta","Cualquier información numérica, alfabética, gráfica o fotográfica sobre una persona física identificada o identificable","Solo las contraseñas, concepto diferente al que se describe en esta pregunta","Información de empresas y corporaciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Incluso una dirección IP dinámica o un identificador de cookie se consideran datos personales si permiten individualizar a un usuario.", noShuffle:false },
  { concept_id:"dig_u3_q4", unit:3, question:"¿Cuáles son los derechos clásicos y ampliados del ciudadano bajo el RGPD (derechos ARSOLP / ARCO)?", options:["Comprar, Vender, Alquilar y Prestar es una accion que no define correctamente este concepto","Acceso, Rectificación, Supresión ('Derecho al Olvido'), Oposición","Votar y Opinar, concepto diferente al que se describe en esta pregunta","Conectarse a internet gratis, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El ciudadano tiene control absoluto sobre sus datos y puede exigir que sean corregidos, eliminados o transferidos a otra empresa.", noShuffle:false },
  { concept_id:"dig_u3_q5", unit:3, question:"¿Qué significa el principio de 'Privacidad desde el Diseño y por Defecto' (Privacy by Design and by Default) exigido por el RGPD?", options:["Diseñar páginas web bonitas, concepto diferente al que se describe en esta pregunta","Que las medidas de seguridad y privacidad deben integrarse desde la fase inicial de concepción técnica del proyecto, y por defecto solo se deben recopilar los datos estrictamente necesarios","Poner un candado en el servidor, concepto diferente al que se describe en esta pregunta","Pedir disculpas tras una filtración es una accion que no define correctamente este concepto"], correct:1, explanation:"La privacidad no es un parche que se añade al final; debe ser un requisito estructural de la arquitectura del software.", noShuffle:false },
  { concept_id:"dig_u3_q6", unit:3, question:"¿Cuál es la cuantía máxima de las sanciones económicas que puede imponer la Agencia de Protección de Datos por infracciones muy graves del RGPD?", options:["Hasta 500 euros, concepto diferente al que se describe en esta pregunta","Hasta 20 millones de euros o el 4% del volumen de negocio total anual global del ejercicio anterior (la cifra que sea mayor)","Hasta 100.000 euros únicamente, concepto diferente al que se describe en esta pregunta","Solo una amonestación por escrito, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las sanciones del RGPD tienen un poder disuasorio descomunal diseñado para obligar a las multinacionales a proteger la privacidad.", noShuffle:false },
  { concept_id:"dig_u3_q7", unit:3, question:"¿En qué plazo máximo debe una empresa notificar una brecha de seguridad de datos personales (Security Breach) a la Agencia de Protección de Datos (AEPD)?", options:["En 1 año, concepto diferente al que se describe en esta pregunta","En un plazo máximo de 72 horas desde que se tenga constancia de la incidencia","En 30 días laborables, concepto diferente al que se describe en esta pregunta","No es obligatorio notificar, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El artículo 33 del RGPD exige notificar en 72 horas si la brecha entraña un riesgo para los derechos y libertades de las personas físicas.", noShuffle:false },
  { concept_id:"dig_u3_q8", unit:3, question:"¿Qué es el DPO (Data Protection Officer / Delegado de Protección de Datos)?", options:["El jefe de ventas, concepto que se aplica en un contexto distinto","La figura experta independiente que supervisa el cumplimiento normativo del RGPD, asesora a la organización y actúa como interlocutor con la autoridad de control (AEPD)","El programador frontend, concepto diferente al que se describe en esta pregunta","El técnico que arregla los ordenadores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es obligatorio en administraciones públicas y en organizaciones que traten datos a gran escala o categorías especiales.", noShuffle:false },
  { concept_id:"dig_u3_q9", unit:3, question:"¿Qué es el ENS (Esquema Nacional de Seguridad) en España?", options:["Un plan de seguridad del ejército, concepto diferente al que se describe en esta pregunta","El marco regulador (Real Decreto 311/2022) que establece los principios básicos y requisitos mínimos de seguridad que deben cumplir los sistemas del sector público y las empresas privadas que les prestan servicios","Un antivirus nacional, concepto diferente al que se describe en esta pregunta","Una red social del estado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Clasifica los sistemas en categorías Básica, Media y Alta según el impacto de una quiebra de confidencialidad, integridad o disponibilidad.", noShuffle:false },
  { concept_id:"dig_u3_q10", unit:3, question:"¿Cuáles son las tres dimensiones de seguridad clásicas de la información (Tríada CIA / CID)?", options:["Cables, Internet y Dispositivos, concepto diferente al que se describe en esta pregunta","Confidencialidad (acceso solo a autorizados), Integridad (datos exactos y no alterados) y Disponibilidad (acceso cuando se necesita)","Copia, Impresión y Descarga, concepto diferente al que se describe en esta pregunta","Código, Interfaz y Datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Toda política o control de ciberseguridad busca preservar alguna de estas tres dimensiones esenciales.", noShuffle:false },
  { concept_id:"dig_u3_q11", unit:3, question:"¿Qué es un ataque de 'Ransomware'?", options:["Un virus que muestra publicidad, concepto diferente al que se describe en esta pregunta","Un software malicioso que cifra y bloquea los archivos y sistemas de la víctima, exigiendo el pago de un rescate económico para proporcionar la clave de descifrado","Un correo no deseado, concepto diferente al que se describe en esta pregunta","Un fallo de hardware, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es una de las mayores amenazas contemporáneas para empresas, hospitales y administraciones públicas.", noShuffle:false },
  { concept_id:"dig_u3_q12", unit:3, question:"¿Qué es el 'Phishing'?", options:["Pescar en un lago, concepto diferente al que se describe en esta pregunta","Una técnica de ingeniería social donde un atacante se hace pasar por una entidad de confianza (banco, empresa, proveedor) mediante correo o web falsa para engañar a la víctima y robar sus contraseñas o datos bancarios","Un ataque de saturación de red, concepto diferente al que se describe en esta pregunta","Un programa para acelerar descargas, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"El factor humano sigue siendo el eslabón más débil: la mayoría de ciberataques exitosos comienzan con un correo de phishing.", noShuffle:false },
  { concept_id:"dig_u3_q13", unit:3, question:"¿Qué es el 'Spear Phishing' frente al phishing tradicional?", options:["Phishing mediante llamadas de voz, concepto diferente al que se describe en esta pregunta","Un ataque de phishing altamente dirigido y personalizado contra una persona u organización concreta, utilizando información previa de la víctima para hacer el engaño extremadamente creíble","Un phishing enviado a millones de personas al azar, concepto diferente al que se describe en esta pregunta","Un ataque contra routers, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"A diferencia del phishing masivo indiscriminado, el spear phishing está investigado meticulosamente para vulnerar objetivos clave (ej: directores financieros).", noShuffle:false },
  { concept_id:"dig_u3_q14", unit:3, question:"¿Qué es la 'Ingeniería Social' en ciberseguridad?", options:["Una carrera universitaria de informática, concepto diferente al que se describe en esta pregunta","El conjunto de técnicas de manipulación psicológica dirigidas a engañar a las personas para que revelen información confidencial o realicen acciones que comprometan la seguridad de la empresa","La programación de redes sociales, concepto que se aplica en un contexto distinto","El diseño ergonómico de oficinas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'No hay parche para la estupidez humana ni para la credulidad': explota la confianza, la urgencia o el miedo de las personas.", noShuffle:false },
  { concept_id:"dig_u3_q15", unit:3, question:"¿Qué es el INCIBE en España?", options:["Un fabricante de ordenadores, concepto diferente al que se describe en esta pregunta","El Instituto Nacional de Ciberseguridad: la entidad de referencia nacional para el desarrollo de la ciberseguridad y la confianza digital de ciudadanos, menores y empresas privadas","Una empresa de telefonía, concepto diferente al que se describe en esta pregunta","Un juzgado especial, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Gestiona el centro de respuesta a incidentes INCIBE-CERT y la línea de ayuda gratuita 017.", noShuffle:false },
  { concept_id:"dig_u3_q16", unit:3, question:"¿Qué es el CCN-CERT en el ámbito público español?", options:["Un club de informática, concepto diferente al que se describe en esta pregunta","El Centro Criptológico Nacional - Computer Emergency Response Team: el organismo responsable de la ciberseguridad en el sector público y sistemas clasificados de la administración","Una empresa de antivirus privada, concepto diferente al que se describe en esta pregunta","Un organismo de patentes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Vela por la seguridad de las administraciones públicas y coordina la respuesta a ciberamenazas estatales.", noShuffle:false },
  { concept_id:"dig_u3_q17", unit:3, question:"¿Qué es la directiva europea NIS 2 (Network and Information Systems Directive)?", options:["Una ley para cables de cobre, concepto diferente al que se describe en esta pregunta","Una directiva de la UE que eleva y homogeniza las exigencias de ciberseguridad, gestión de riesgos y notificación de incidentes para entidades esenciales e importantes en sectores críticos (energía, salud, banca, digital)","Una ley sobre el 5G, concepto diferente al que se describe en esta pregunta","Una normativa de comercio minorista, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Amplía las obligaciones y responsabilidades legales directas de los consejos de administración ante fallos de ciberseguridad.", noShuffle:false },
  { concept_id:"dig_u3_q18", unit:3, question:"¿Qué es la 'Anonimización' frente a la 'Seudonimización' de datos personales?", options:["Son sinónimos, concepto diferente al que se describe en esta pregunta","La seudonimización sustituye identificadores por códigos pero permite reidentificar a la persona con información adicional separada (sigue siendo dato personal); la anonimización destruye irreversiblemente cualquier posibilidad de identificar a la persona (deja de ser dato personal)","La anonimización es temporal, concepto diferente al que se describe en esta pregunta","La seudonimización es ilegal, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los datos verdaderamente anonimizados quedan excluidos del ámbito de aplicación del RGPD.", noShuffle:false },
  { concept_id:"dig_u3_q19", unit:3, question:"¿Qué es un MFA (Multi-Factor Authentication / Autenticación Multifactor)?", options:["Introducir la contraseña dos veces seguidas, concepto diferente al que se describe en esta pregunta","Un método de control de acceso que exige al usuario aportar al menos dos factores de prueba independientes de distintas categorías: algo que sabe (contraseña), algo que tiene (móvil, token) o algo que es (biometría)","Tener dos usuarios con la misma clave, concepto diferente al que se describe en esta pregunta","Usar dos teclados, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Invalida el 99% de los ataques de robo de contraseñas, ya que el atacante carece del segundo factor físico en posesión de la víctima.", noShuffle:false },
  { concept_id:"dig_u3_q20", unit:3, question:"¿Qué es una vulnerabilidad de 'Día Cero' (Zero-Day)?", options:["Una vulnerabilidad que se arregla en cero días, concepto diferente al que se describe en esta pregunta","Un fallo de seguridad en el software desconocido para el fabricante o para el público general, para el cual no existe parche oficial disponible y que los atacantes pueden explotar libremente","Un error que ocurre el día 1 de cada mes, concepto diferente al que se describe en esta pregunta","Un software que caduca en 24 horas, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Se llama día cero porque los defensores han tenido cero días de margen para desarrollar una contramedida desde que se descubre la amenaza activa.", noShuffle:false },
  { concept_id:"dig_u3_q21", unit:3, question:"¿Qué es un SGSI (Sistema de Gestión de la Seguridad de la Información) y qué estándar internacional lo certifica?", options:["Un software antivirus certificado por Google, que aunque es una herramienta util, no corresponde a esta definicion","Un conjunto de políticas y procedimientos sistemáticos para gestionar riesgos de seguridad corporativos, certificado por la norma internacional ISO/IEC 27001","Un cortafuegos certificado por Microsoft, concepto diferente al que se describe en esta pregunta","Una base de datos de auditoría, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La certificación ISO 27001 acredita formalmente que una organización gestiona sus activos y riesgos digitales de forma rigurosa y continua.", noShuffle:false },
  { concept_id:"dig_u3_q22", unit:3, question:"¿Qué es el principio de 'Mínimo Privilegio' (Least Privilege) en gestión de accesos corporativos?", options:["Pagar el salario mínimo, concepto diferente al que se describe en esta pregunta","Garantizar que cada usuario, proceso o programa disponga estrictamente de los permisos y accesos indispensables para realizar su función laboral y nada más","No permitir el uso de internet, concepto diferente al que se describe en esta pregunta","Dar permisos de administrador a todos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si la cuenta de un empleado es comprometida por malware, el atacante no puede moverse lateralmente ni acceder a datos confidenciales ajenos a ese puesto.", noShuffle:false },
  { concept_id:"dig_u3_q23", unit:3, question:"¿Qué es una auditoría de 'Pentesting' (Pruebas de Penetración o Hacking Ético)?", options:["Un formateo de ordenadores, concepto diferente al que se describe en esta pregunta","Un ejercicio autorizado donde profesionales de seguridad simulan ciberataques reales contra los sistemas de la empresa para identificar vulnerabilidades antes de que los ciberdelincuentes las exploten","Una prueba de velocidad de red, concepto diferente al que se describe en esta pregunta","Un examen de mecanografía, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se clasifica en Caja Negra (sin información previa), Caja Blanca (con código y planos) o Caja Gris.", noShuffle:false },
  { concept_id:"dig_u3_q24", unit:3, question:"¿Qué es un SOC (Security Operations Center / Centro de Operaciones de Seguridad)?", options:["Un almacén de ordenadores, concepto diferente al que se describe en esta pregunta","Un equipo centralizado de analistas de seguridad que monitoriza, detecta","Un servidor de bases de datos, concepto diferente al que se describe en esta pregunta","Una reunión de directivos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El SOC actúa como el puesto de mando defensivo y de vigilancia activa contra ciberataques.", noShuffle:false },
  { concept_id:"dig_u3_q25", unit:3, question:"¿Qué es un sistema SIEM (Security Information and Event Management)?", options:["Un procesador de textos, concepto diferente al que se describe en esta pregunta","Una plataforma de software que centraliza, agrega y correlaciona registros (logs) y eventos de seguridad generados por toda la red para alertar en tiempo real sobre comportamientos anómalos o intrusiones","Un gestor de correos, concepto diferente al que se describe en esta pregunta","Un sistema de backups, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Herramientas como Splunk o Elastic SIEM permiten detectar patrones sutiles de ataques coordinados que pasarían inadvertidos en logs aislados.", noShuffle:false },
  { concept_id:"dig_u3_q26", unit:3, question:"¿Qué es una política de 'Escritorio Limpio y Pantalla Limpia' (Clear Desk and Clear Screen Policy)?", options:["Limpiar el polvo de la mesa todos los días, concepto diferente al que se describe en esta pregunta","Una norma de seguridad física que exige bloquear la sesión del ordenador al levantarse y no dejar documentos confidenciales ni notas con contraseñas visibles sobre la mesa","No usar pantallas grandes, concepto diferente al que se describe en esta pregunta","Trabajar sin mesa, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita el 'Shoulder Surfing' (mirar por encima del hombro) y el robo de información sensible por visitas o personal de limpieza.", noShuffle:false },
  { concept_id:"dig_u3_q27", unit:3, question:"¿Qué es un 'Plan de Continuidad de Negocio' (BCP - Business Continuity Plan)?", options:["Un plan para no jubilarse, concepto diferente al que se describe en esta pregunta","Un documento estratégico integral que define los procedimientos y recursos necesarios para que las operaciones esenciales de la empresa sigan funcionando durante y después de un desastre o ciberataque crítico","Un presupuesto de marketing, concepto diferente al que se describe en esta pregunta","Un contrato de seguros, que pertenece a un ambito distinto del aqui estudiado"], correct:1, explanation:"Asegura la supervivencia de la organización ante catástrofes físicas, cortes eléctricos prolongados o secuestros informáticos.", noShuffle:false },
  { concept_id:"dig_u3_q28", unit:3, question:"¿Qué es un DRP (Disaster Recovery Plan / Plan de Recuperación ante Desastres) frente al BCP?", options:["Son sinónimos, concepto diferente al que se describe en esta pregunta","El BCP abarca la continuidad de todo el negocio y personas","El DRP es solo para terremotos, concepto diferente al que se describe en esta pregunta","El BCP solo aplica a bancos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El DRP es la vertiente puramente tecnológica e informática del plan global de continuidad.", noShuffle:false },
  { concept_id:"dig_u3_q29", unit:3, question:"¿Por qué las copias de seguridad de una empresa deben contar con al menos una versión 'Inmutable' o aislada de la red (Air-Gapped)?", options:["Para que pesen menos, concepto diferente al que se describe en esta pregunta","Porque el ransomware moderno busca activamente los servidores de backup conectados a la red corporativa y los destruye o cifra en primer lugar antes de atacar los sistemas principales","Porque no caben en discos duros, concepto diferente al que se describe en esta pregunta","Para que no se calienten, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las copias inmutables (WORM - Write Once, Read Many) o desconectadas físicamente garantizan que siempre existirá una versión limpia para restaurar sin pagar el rescate.", noShuffle:false },
  { concept_id:"dig_u3_q30", unit:3, question:"¿Qué es la 'Gestión de Parches' (Patch Management) en una organización digital?", options:["Poner pegatinas en los ordenadores, concepto diferente al que se describe en esta pregunta","El proceso sistemático de adquirir, probar y desplegar actualizaciones de seguridad y parches en el software, sistemas operativos y firmware para cerrar vulnerabilidades conocidas antes de que sean explotadas","Comprar software nuevo es una accion que no define correctamente este concepto","Reparar cables rotos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La gran mayoría de brechas masivas explotan vulnerabilidades para las que existía un parche de seguridad publicado meses atrás que la empresa no llegó a instalar.", noShuffle:false },
  { concept_id:"dig_u3_q31", unit:3, question:"¿Qué es el 'Doble Candado' o Doble Extorsión en los ataques modernos de Ransomware?", options:["Pagar dos veces la factura, concepto diferente al que se describe en esta pregunta","Los atacantes no solo cifran los sistemas de la empresa para paralizarla","Usar dos contraseñas, concepto diferente al que se describe en esta pregunta","Bloquear dos ordenadores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Inutiliza las copias de seguridad como única defensa: aunque la empresa pueda restaurar sus datos, afronta multas por filtración y daños de imagen.", noShuffle:false },
  { concept_id:"dig_u3_q32", unit:3, question:"¿Qué es el 'Consentimiento Válido' bajo el RGPD para tratar datos personales?", options:["Cualquier clic en la página, concepto diferente al que se describe en esta pregunta","Una manifestación de voluntad libre, específica, informada e inequívoca mediante una acción afirmativa clara (las casillas premarcadas por defecto están terminantemente prohibidas)","Un correo electrónico enviado al usuario, concepto diferente al que se describe en esta pregunta","El silencio del usuario, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El usuario debe marcar la casilla activamente; el consentimiento tácito o por omisión es ilegal en la Unión Europea.", noShuffle:false },
  { concept_id:"dig_u3_q33", unit:3, question:"¿Qué es la 'Evaluación de Impacto en la Protección de Datos' (EIPD / DPIA)?", options:["Un informe sobre el consumo de energía, concepto diferente al que se describe en esta pregunta","Un análisis previo obligatorio cuando un tratamiento de datos entraña un alto riesgo para los derechos y libertades de las personas","Un balance contable, concepto diferente al que se describe en esta pregunta","Una auditoría de hardware, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite evaluar los riesgos antes de comenzar el tratamiento y diseñar medidas paliativas obligatorias.", noShuffle:false },
  { concept_id:"dig_u3_q34", unit:3, question:"¿Qué es el 'Data Breach Notification' a los propios interesados (afectados)?", options:["Enviarles publicidad de disculpa, concepto diferente al que se describe en esta pregunta","La obligación de comunicar la brecha directamente a los ciudadanos afectados sin dilación indebida cuando sea probable que entrañe un alto riesgo para sus derechos","Publicarlo en el periódico del domingo, concepto diferente al que se describe en esta pregunta","No es obligatorio avisar al usuario, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a los usuarios tomar medidas preventivas (como cambiar contraseñas o cancelar tarjetas de crédito bancarias).", noShuffle:false },
  { concept_id:"dig_u3_q35", unit:3, question:"¿Qué es una 'Cookie de Terceros' y por qué están en proceso de obsolescencia por motivos de privacidad?", options:["Una galleta de tres sabores, concepto diferente al que se describe en esta pregunta","Cookies establecidas por un dominio diferente al que el usuario está visitando, utilizadas tradicionalmente por redes publicitarias para rastrear la navegación a través de múltiples webs sin control del usuario","Cookies de tres megabytes, concepto diferente al que se describe en esta pregunta","Cookies caducadas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Navegadores como Safari y Firefox ya las bloquean por defecto y Chrome está reduciendo su uso en favor de Privacy Sandbox.", noShuffle:false },
  { concept_id:"dig_u3_q36", unit:3, question:"¿Qué es el 'Ataque de Man-in-the-Browser' (MitB)?", options:["Un virus que borra el navegador, concepto diferente al que se describe en esta pregunta","Un troyano que infecta el navegador web de la víctima y modifica transacciones bancarias o datos enviados en tiempo real de forma invisible para el usuario y el servidor seguro HTTPS","Un complemento de Chrome, concepto diferente al que se describe en esta pregunta","Una extensión para guardar contraseñas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Intercepta los datos antes de que el navegador los cifre para enviarlos por TLS.", noShuffle:false },
  { concept_id:"dig_u3_q37", unit:3, question:"¿Qué es el 'DLP' (Data Loss Prevention / Prevención de Fuga de Datos)?", options:["Un cable de red seguro, concepto diferente al que se describe en esta pregunta","Una solución de software que detecta, monitoriza y bloquea automáticamente la salida no autorizada o copia de información confidencial (ej","Un sistema de backups, que aunque es una herramienta util, no corresponde a esta definicion","Un cortafuegos doméstico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Impide que un empleado desleal o un malware copie archivos estratégicos a un pendrive USB o los suba a un almacenamiento personal.", noShuffle:false },
  { concept_id:"dig_u3_q38", unit:3, question:"¿Qué es la biometría (huella, reconocimiento facial) y qué consideración tiene en el RGPD?", options:["Son datos corrientes como el código postal, concepto diferente al que se describe en esta pregunta","Son 'Categorías Especiales de Datos' (datos especialmente protegidos) debido a que identifican de forma unívoca a una persona y su filtración es irreversible (no puedes cambiar de huella como de contraseña)","Son datos de acceso libre, concepto diferente al que se describe en esta pregunta","Son datos que no se pueden almacenar, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Su tratamiento está prohibido por defecto salvo excepciones estrictas y exige siempre una Evaluación de Impacto (EIPD).", noShuffle:false },
  { concept_id:"dig_u3_q39", unit:3, question:"¿Qué es el 'Ataque de Envenenamiento de Modelos' (Data Poisoning) en sistemas de Inteligencia Artificial?", options:["Verter líquidos en el servidor, concepto diferente al que se describe en esta pregunta","Un ataque malicioso que manipula los datos de entrenamiento de un modelo de IA para que aprenda patrones sesgados o incluya puertas traseras intencionadas en sus predicciones","Un virus que sobrecalienta la GPU, concepto diferente al que se describe en esta pregunta","Borrar la base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Vulnera la integridad del sistema de toma de decisiones automatizado desde su base de aprendizaje.", noShuffle:false },
  { concept_id:"dig_u3_q40", unit:3, question:"¿Qué papel juega la 'Criptografía Post-Cuántica' (PQC) en la ciberseguridad del futuro inmediato?", options:["Un juego de ordenador, concepto diferente al que se describe en esta pregunta","Nuevos algoritmos criptográficos basados en problemas matemáticos inmunes a los futuros ordenadores cuánticos (capaces de romper RSA y curvas elípticas en segundos) estandarizados por el NIST","Criptografía que viaja en el tiempo, concepto diferente al que se describe en esta pregunta","Un tipo de blockchain, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Garantiza que las comunicaciones cifradas hoy no puedan ser interceptadas y descifradas en el futuro por ordenadores cuánticos (ataque 'Harvest Now, Decrypt Later').", noShuffle:false },
  { concept_id:"dig_u3_q41", unit:3, question:"¿Qué es el 'Registro de Actividades de Tratamiento' (RAT) obligatorio para empresas bajo el RGPD?", options:["La lista de asistencia de los trabajadores, concepto que se aplica en un contexto distinto","Un documento interno formal donde la empresa detalla qué datos personales trata, con qué fines lícitos, a quién los comunica, los plazos de conservación y las medidas de seguridad adoptadas","El historial de internet de los ordenadores, concepto que se aplica en un contexto distinto","El libro de contabilidad, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Sustituye a la antigua obligación de inscribir ficheros ante la AEPD y debe estar a disposición de la autoridad si se solicita.", noShuffle:false },
  { concept_id:"dig_u3_q42", unit:3, question:"¿Qué es la 'Higiene Digital' básica en una organización?", options:["Limpiar las pantallas con toallitas, concepto diferente al que se describe en esta pregunta","El conjunto elemental y cotidiano de buenas prácticas de ciberseguridad que todo empleado debe aplicar: contraseñas robustas y únicas, uso de gestores de claves, MFA, desconfianza ante correos extraños y actualización de software","Instalar diez antivirus a la vez es una accion que no define correctamente este concepto","Apagar el ordenador cada 2 horas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La higiene digital previene más del 80% de los incidentes de seguridad ordinarios en las empresas.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 4 — Metodologías Ágiles, Design Thinking e Innovación
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dig_u4_q1", unit:4, question:"¿Qué es el 'Design Thinking'?", options:["Un software de diseño vectorial, que aunque es una herramienta util, no corresponde a esta definicion","Una metodología de resolución de problemas e innovación centrada en las personas (Human-Centered Design) que combina empatía, creatividad, experimentación y prototipado iterativo","Un tipo de framework de CSS, concepto diferente al que se describe en esta pregunta","Un manual de dibujo artístico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Nacida en la Universidad de Stanford y popularizada por IDEO, sitúa las necesidades reales del usuario en el núcleo de la solución.", noShuffle:false },
  { concept_id:"dig_u4_q2", unit:4, question:"¿Cuáles son las 5 fases secuenciales e iterativas del proceso de Design Thinking según Stanford d.school?", options:["Planificar, Ejecutar, Revisar, Cobrar y Entregar","Empatizar, Definir, Idear, Prototipar y Testear (Evaluar)","Comprar, Instalar, Configurar, Probar y Desplegar","Diseñar, Programar, Probar, Vender y Mantener"], correct:1, explanation:"Es un proceso no lineal: los hallazgos en la fase de testeo suelen obligar a volver a empatizar o redefinir el problema.", noShuffle:false },
  { concept_id:"dig_u4_q3", unit:4, question:"¿Cuál es el objetivo primordial de la fase 'Empatizar' en Design Thinking?", options:["Diseñar logotipos atractivos, concepto diferente al que se describe en esta pregunta","Comprender profundamente a los usuarios en su propio contexto: sus vivencias, necesidades no verbalizadas, emociones, hábitos y puntos de dolor mediante entrevistas y observación directa","Definir el precio de venta, concepto diferente al que se describe en esta pregunta","Escribir el código fuente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Desprenderse de los propios prejuicios y ponerse verdaderamente en los zapatos de quienes usarán el producto.", noShuffle:false },
  { concept_id:"dig_u4_q4", unit:4, question:"¿Qué se formula en la fase 'Definir' de Design Thinking como brújula del proyecto?", options:["El presupuesto contable, concepto diferente al que se describe en esta pregunta","El 'Point of View' (POV) o declaración clara del problema centrada en el usuario (ej","El contrato de compra, concepto que se aplica en un contexto distinto","El esquema de base de datos, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Aterriza los descubrimientos de la empatía en un reto de diseño concreto, accionable y delimitado.", noShuffle:false },
  { concept_id:"dig_u4_q5", unit:4, question:"¿Qué regla de oro rige las sesiones de Brainstorming durante la fase 'Idear' de Design Thinking?", options:["Criticar las ideas malas de inmediato, concepto diferente al que se describe en esta pregunta","Fomentar la cantidad sobre la calidad, aplazar todo juicio o crítica negativa, dar la bienvenida a ideas descabelladas y construir sobre las ideas de los demás","Hablar de una en una por orden de jerarquía, concepto diferente al que se describe en esta pregunta","Buscar solo soluciones baratas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El pensamiento divergente requiere un entorno psicológicamente seguro donde no se censure ninguna ocurrencia inicial.", noShuffle:false },
  { concept_id:"dig_u4_q6", unit:4, question:"¿Qué significa el lema 'Falla rápido y falla barato' (Fail Fast, Fail Cheap) en la fase de 'Prototipar'?", options:["Que el producto debe romperse en las tiendas, concepto diferente al que se describe en esta pregunta","Construir maquetas sencillas de bajo coste en minutos u horas para validar hipótesis con usuarios de inmediato antes de gastar meses y miles de euros en desarrollo definitivo","No cobrar por el trabajo, concepto diferente al que se describe en esta pregunta","Trabajar con desgana, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Descubrir que una idea es inviable en un prototipo de papel cuesta 5 euros; descubrirlo tras programarla cuesta 50.000 euros.", noShuffle:false },
  { concept_id:"dig_u4_q7", unit:4, question:"¿Cuál es la diferencia fundamental entre el modelo tradicional en Cascada (Waterfall) y las Metodologías Ágiles (Agile)?", options:["Las metodologías ágiles no planifican nada, concepto diferente al que se describe en esta pregunta","El modelo en cascada es lineal, rígido y secuencial donde los requisitos se fijan al inicio y el producto solo se entrega al final; Agile es iterativo e incremental, entregando valor funcional en ciclos cortos adaptables a los cambios","Waterfall es más rápido siempre, concepto diferente al que se describe en esta pregunta","Agile no tiene pruebas de calidad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Agile abraza el cambio continuo como una ventaja competitiva frente a la ilusión del plan maestro predictivo a 2 años.", noShuffle:false },
  { concept_id:"dig_u4_q8", unit:4, question:"¿Qué hito fundacional dio origen formal al movimiento ágil en 2001?", options:["La invención de internet, concepto que se aplica en un contexto distinto","La publicación del 'Manifiesto por el Desarrollo Ágil de Software' (Manifiesto Ágil) por 17 líderes de la industria en Snowbird, Utah","El lanzamiento de Windows XP, concepto que se aplica en un contexto distinto","La fundación de Google, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Estableció 4 valores clave y 12 principios que transformaron la gestión de proyectos en todo el planeta.", noShuffle:false },
  { concept_id:"dig_u4_q9", unit:4, question:"¿Cuál de los siguientes es uno de los cuatro valores esenciales del Manifiesto Ágil?", options:["Procesos y herramientas por encima de los individuos","Individuos e interacciones sobre procesos y herramientas","Contratos exhaustivos sobre colaboración con el cliente","Seguir un plan estricto sobre respuesta al cambio"], correct:1, explanation:"Los 4 valores priorizan: Personas sobre procesos, Software funcionando sobre documentación exhaustiva, Colaboración sobre negociación y Respuesta al cambio sobre seguir un plan.", noShuffle:false },
  { concept_id:"dig_u4_q10", unit:4, question:"¿Qué es el marco de trabajo 'Scrum'?", options:["Una jugada de rugby sin relación con software, concepto diferente al que se describe en esta pregunta","Un marco de trabajo ágil iterativo e incremental para proyectos complejos donde el trabajo se estructura en ciclos temporales fijos llamados Sprints de 1 a 4 semanas","Un compilador de código, concepto diferente al que se describe en esta pregunta","Un editor de texto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Scrum fomenta la autoorganización del equipo, la inspección continua y la adaptación empírica del producto.", noShuffle:false },
  { concept_id:"dig_u4_q11", unit:4, question:"¿Cuáles son los tres roles definidos formalmente en el marco Scrum?", options:["Jefe de Proyecto, Analista y Programador, concepto diferente al que se describe en esta pregunta","Product Owner (Dueño de Producto), Scrum Master y Developers (Equipo de Desarrollo)","Director, Subdirector y Secretario, concepto diferente al que se describe en esta pregunta","Diseñador, Tester y Operador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Scrum elimina la figura del gestor de proyecto tradicional distribuyendo responsabilidades de visión, facilitación y ejecución técnica.", noShuffle:false },
  { concept_id:"dig_u4_q12", unit:4, question:"¿Cuál es la responsabilidad principal del 'Product Owner' en Scrum?", options:["Asignar tareas diarias a los programadores, concepto diferente al que se describe en esta pregunta","Maximizar el valor del producto gestionando, ordenando y priorizando los elementos del Product Backlog representando las necesidades de usuarios y negocio","Resolver impedimentos técnicos del equipo, concepto diferente al que se describe en esta pregunta","Organizar las reuniones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es la única persona responsable de decidir 'QUÉ' se construye y en qué orden de prioridad.", noShuffle:false },
  { concept_id:"dig_u4_q13", unit:4, question:"¿Cuál es la responsabilidad principal del 'Scrum Master'?", options:["Escribir el código más difícil, concepto diferente al que se describe en esta pregunta","Actuar como líder servicial que facilita la aplicación de Scrum","Gestionar el presupuesto contable, concepto diferente al que se describe en esta pregunta","Decidir la arquitectura de base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"No es el jefe del equipo, sino un facilitador y coach que asegura la efectividad de las ceremonias y el bienestar del equipo.", noShuffle:false },
  { concept_id:"dig_u4_q14", unit:4, question:"¿Qué es el 'Product Backlog' en Scrum?", options:["El código de respaldo en disco, concepto que se aplica en un contexto distinto","Una lista ordenada y dinámica de todo lo que se sabe que es necesario para mejorar el producto (historias de usuario, funciones, bugs, mejoras técnicas)","El historial de commits de Git, concepto que se aplica en un contexto distinto","La lista de empleados, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Es la única fuente autoritativa de requisitos para cualquier cambio a realizar en el producto.", noShuffle:false },
  { concept_id:"dig_u4_q15", unit:4, question:"¿Qué es un 'Sprint' en Scrum?", options:["Correr 100 metros en la oficina, concepto diferente al que se describe en esta pregunta","Un contenedor temporal de duración fija (time-box) de un mes o menos durante el cual se crea un incremento de producto utilizable y potencialmente desplegable","Una reunión de emergencia, concepto diferente al que se describe en esta pregunta","Un despido colectivo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El ritmo constante de los Sprints proporciona predictibilidad al desarrollo y a los clientes.", noShuffle:false },
  { concept_id:"dig_u4_q16", unit:4, question:"¿Qué es el 'Daily Scrum' (o Stand-up Meeting)?", options:["Una comida de equipo, concepto diferente al que se describe en esta pregunta","Un evento diario de máximo 15 minutos para que los desarrolladores inspeccionen el progreso hacia el Objetivo del Sprint y sincronicen el plan de trabajo para las siguientes 24 horas","Un informe semanal por escrito, concepto diferente al que se describe en esta pregunta","Una sesión de evaluación de jefes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Tradicionalmente se realiza de pie para mantener la reunión concisa y enfocada en lo operativo.", noShuffle:false },
  { concept_id:"dig_u4_q17", unit:4, question:"¿Qué es la 'Sprint Review' (Revisión del Sprint)?", options:["Una auditoría contable secreta, concepto diferente al que se describe en esta pregunta","Una reunión al final del Sprint donde el equipo muestra el incremento de producto terminado y funcionando a los stakeholders y clientes para recabar su feedback","Un examen de programación, concepto diferente al que se describe en esta pregunta","Una reunión para quejarse de los compañeros, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite inspeccionar el resultado real y adaptar el Product Backlog según las reacciones de los clientes.", noShuffle:false },
  { concept_id:"dig_u4_q18", unit:4, question:"¿Qué es la 'Sprint Retrospective' (Retrospectiva del Sprint)?", options:["Mirar fotos del pasado, concepto diferente al que se describe en esta pregunta","Una reunión al final del Sprint dedicada exclusivamente a que el equipo reflexione sobre sus propios procesos, relaciones humanas y herramientas para identificar mejoras continuas aplicables en el siguiente Sprint","Una reunión de ventas, concepto diferente al que se describe en esta pregunta","La firma del contrato, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es el motor de la mejora continua (Kaizen): ¿Qué fue bien? ¿Qué podemos mejorar? ¿Qué acciones tomaremos?", noShuffle:false },
  { concept_id:"dig_u4_q19", unit:4, question:"¿Qué es una 'Historia de Usuario' (User Story) y cuál es su formato estándar?", options:["Una novela de ciencia ficción","Una descripción breve de una funcionalidad escrita desde la perspectiva del usuario final: 'Como [rol], quiero [funcionalidad] para [beneficio/valor]'","Un diagrama UML completo","Un caso de prueba técnico"], correct:1, explanation:"Pone el foco en el valor que recibe el usuario humano y no en la especificación técnica fría.", noShuffle:false },
  { concept_id:"dig_u4_q20", unit:4, question:"¿Qué es la 'Definition of Done' (DoD - Definición de Hecho) en Scrum?", options:["La hora de salida de la oficina, que puede confundirse con este termino en contabilidad general","Un acuerdo formal compartido que describe los criterios de calidad que debe satisfacer un elemento del backlog para considerarse terminado","El cierre del contrato, concepto diferente al que se describe en esta pregunta","Un checkbox en Jira, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita la trampa del 'está casi terminado' y garantiza que solo se entrega software verdaderamente listo para producción.", noShuffle:false },
  { concept_id:"dig_u4_q21", unit:4, question:"¿Qué es la metodología 'Kanban' y de dónde procede históricamente?", options:["Un arte marcial japonesa, concepto diferente al que se describe en esta pregunta","Un método ágil de gestión visual del flujo de trabajo originado en el sistema de producción 'Just in Time' de Toyota que utiliza tarjetas en un tablero para visualizar tareas y limitar el trabajo en curso (WIP)","Un framework de React, concepto diferente al que se describe en esta pregunta","Un software de bases de datos, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Kanban ('tarjeta visual') busca optimizar el flujo continuo sin imponer sprints fijos como Scrum.", noShuffle:false },
  { concept_id:"dig_u4_q22", unit:4, question:"¿Cuál es la regla más importante en un tablero Kanban para evitar cuellos de botella y sobrecarga?", options:["Tener muchas columnas, concepto diferente al que se describe en esta pregunta","Limitar el Trabajo en Curso (WIP - Work In Progress Limits) fijando un número máximo de tareas permitidas en cada estado a la vez","Trabajar en 10 tareas a la vez, concepto diferente al que se describe en esta pregunta","No hablar entre compañeros, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'Stop starting, start finishing' (Deja de empezar cosas y empieza a terminarlas): fomenta el foco y la velocidad de entrega.", noShuffle:false },
  { concept_id:"dig_u4_q23", unit:4, question:"¿Qué es el 'Lead Time' frente al 'Cycle Time' en analítica ágil y Kanban?", options:["Son sinónimos, concepto diferente al que se describe en esta pregunta","Lead Time es el tiempo total desde que el cliente solicita una tarea hasta que se entrega terminada; Cycle Time es el tiempo desde que el equipo empieza a trabajar activamente en ella hasta que concluye","Lead Time es el tiempo de vacaciones, concepto diferente al que se describe en esta pregunta","Cycle Time es la velocidad del procesador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Optimizar el Cycle Time reduce el desperdicio y proporciona entregas predecibles a los usuarios.", noShuffle:false },
  { concept_id:"dig_u4_q24", unit:4, question:"¿Qué es la metodología 'Lean Startup' de Eric Ries?", options:["Una empresa que no gasta dinero, concepto diferente al que se describe en esta pregunta","Una metodología para crear empresas y productos basada en ciclos ultrarrápidos de retroalimentación","Un software para calcular nóminas, que aunque es una herramienta util, no corresponde a esta definicion","Un curso de finanzas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Busca eliminar el desperdicio de construir productos completos que nadie desea comprar.", noShuffle:false },
  { concept_id:"dig_u4_q25", unit:4, question:"¿Qué es un 'MVP' (Producto Mínimo Viable)?", options:["El jugador más valioso de un partido de fútbol, concepto diferente al que se describe en esta pregunta","La versión de un nuevo producto que permite a un equipo recopilar la máxima cantidad de aprendizaje validado sobre los clientes con el menor esfuerzo y coste posible","Un producto defectuoso e incompleto, concepto diferente al que se describe en esta pregunta","El prototipo final listo para cotizar en bolsa, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"No es un producto a medio hacer sin calidad; es la versión más sencilla que resuelve el problema central del cliente para verificar la demanda real.", noShuffle:false },
  { concept_id:"dig_u4_q26", unit:4, question:"¿Qué significa el término 'Pivotar' en Lean Startup?", options:["Girar sobre una pierna en baloncesto, concepto diferente al que se describe en esta pregunta","Efectuar un cambio estructural estratégico en el modelo de negocio (ej","Cerrar la empresa definitivamente, concepto diferente al que se describe en esta pregunta","Despedir a los fundadores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Mantener la visión global pero cambiando la estrategia táctica (como cuando Slack pasó de ser un videojuego fallido a una herramienta de chat).", noShuffle:false },
  { concept_id:"dig_u4_q27", unit:4, question:"¿Qué es el 'Product-Market Fit' (Encaje Producto-Mercado)?", options:["Un tipo de tienda de ropa, concepto diferente al que se describe en esta pregunta","El estado en el que una empresa comprueba que su producto satisface con éxito una demanda real potente de un mercado rentable y en crecimiento (los clientes compran, recomiendan y retienen el producto)","Hacer publicidad en televisión es una accion que no define correctamente este concepto","Vender barato es una accion que no define correctamente este concepto"], correct:1, explanation:"Alcanzar el Product-Market Fit es el hito crítico antes del cual no se debe invertir masivamente en escalado o marketing agresivo.", noShuffle:false },
  { concept_id:"dig_u4_q28", unit:4, question:"¿Qué es la técnica de estimación ágil 'Planning Poker'?", options:["Apostar dinero real en el trabajo es una accion que no define correctamente este concepto","Una técnica colaborativa basada en consenso donde los desarrolladores estiman el esfuerzo relativo de historias de usuario jugando cartas con la secuencia de Fibonacci modificada (1, 2, 3, 5, 8, 13...)","Un juego de azar, concepto diferente al que se describe en esta pregunta","Una reunión sin límite de tiempo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita el sesgo de anclaje (donde el primer desarrollador en hablar condiciona las opiniones de los demás) fomentando debate enriquecedor.", noShuffle:false },
  { concept_id:"dig_u4_q29", unit:4, question:"¿Qué representa un 'Story Point' (Punto de Historia) en estimación ágil frente a estimar en horas?", options:["Un euro por cada punto, concepto diferente al que se describe en esta pregunta","Una medida relativa adimensional que combina la complejidad técnica","Una hora fija de trabajo, concepto diferente al que se describe en esta pregunta","El número de líneas de código, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Estimar en esfuerzo relativo es mucho más certero y resistente a variaciones individuales que estimar en horas cronológicas absolutas.", noShuffle:false },
  { concept_id:"dig_u4_q30", unit:4, question:"¿Qué es la 'Velocidad del Equipo' en Scrum?", options:["La velocidad al escribir en el teclado, concepto diferente al que se describe en esta pregunta","La cantidad media de Puntos de Historia que el equipo completa con éxito cumpliendo la Definition of Done durante un Sprint","La velocidad de conexión a internet, concepto que se aplica en un contexto distinto","El número de tareas asignadas, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Permite calcular empíricamente la capacidad de trabajo futura y planificar lanzamientos con rigor estadístico.", noShuffle:false },
  { concept_id:"dig_u4_q31", unit:4, question:"¿Qué es un 'Burndown Chart' (Gráfico de Trabajo Pendiente)?", options:["Un gráfico de incendios forestales, concepto diferente al que se describe en esta pregunta","Una representación gráfica del trabajo restante que queda por completar frente al tiempo transcurrido del Sprint, mostrando si el equipo avanza al ritmo necesario para alcanzar el objetivo","Un informe de gastos, concepto diferente al que se describe en esta pregunta","Un organigrama empresarial, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Una línea ideal descendente sirve como guía para advertir desviaciones a mitad del Sprint.", noShuffle:false },
  { concept_id:"dig_u4_q32", unit:4, question:"¿Qué es la 'Deuda Técnica' (Technical Debt) en desarrollo de software?", options:["Pedir un préstamo bancario para comprar ordenadores","El coste futuro implícito de haber elegido una solución técnica rápida","Comprar servidores a plazos es una accion que no define correctamente este concepto","Un fallo contable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si la deuda técnica no se amortiza refactorizando, llega a paralizar por completo el desarrollo de nuevas funcionalidades.", noShuffle:false },
  { concept_id:"dig_u4_q33", unit:4, question:"¿Qué es el 'Design Sprint' creado por Jake Knapp en Google Ventures?", options:["Una carrera deportiva de diseñadores, concepto diferente al que se describe en esta pregunta","Un proceso estructurado de 5 días de duración que comprime meses de trabajo para responder preguntas críticas de negocio mediante diseño, prototipado rápido y testeo con clientes reales","Un mes de desarrollo continuo, concepto diferente al que se describe en esta pregunta","Un hackathon nocturno, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Lunes: Entender, Martes: Esbozar, Miércoles: Decidir, Jueves: Prototipar, Viernes: Testear con 5 usuarios.", noShuffle:false },
  { concept_id:"dig_u4_q34", unit:4, question:"¿Qué es el 'Kamino' o Pensamiento Lateral en innovación?", options:["Caminar en línea recta, concepto diferente al que se describe en esta pregunta","Una técnica de pensamiento creativo que busca resolver problemas mediante métodos no ortodoxos, indirectos e imaginativos que la lógica tradicional lineal pasaría por alto","Un tipo de yoga, concepto diferente al que se describe en esta pregunta","Un proceso contable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Formulado por Edward de Bono, rompe bloqueos mentales abordando los retos desde ángulos inesperados.", noShuffle:false },
  { concept_id:"dig_u4_q35", unit:4, question:"¿Qué es un 'Mapa de Empatía' en Design Thinking?", options:["Un mapa GPS de la ciudad, concepto diferente al que se describe en esta pregunta","Una herramienta visual dividida en cuatro cuadrantes que sintetiza qué dice, qué hace, qué piensa y qué siente el usuario, además de sus esfuerzos y resultados deseados","Un informe médico, concepto diferente al que se describe en esta pregunta","Un contrato de trabajo, que pertenece a un ambito distinto del aqui estudiado"], correct:1, explanation:"Ayuda a todo el equipo de producto a ponerse de acuerdo sobre el perfil humano real al que sirven.", noShuffle:false },
  { concept_id:"dig_u4_q36", unit:4, question:"¿Qué significa el acrónimo 'SCAMPER' como técnica de creatividad?", options:["Un software antivirus, que aunque es una herramienta util, no corresponde a esta definicion","Una técnica de generación de ideas que estimula la innovación aplicando 7 acciones: Sustituir, Combinar, Adaptar, Modificar/Magnificar, Poner en otros usos, Eliminar y Reordenar/Invertir","Un tipo de malware de estafa, concepto diferente al que se describe en esta pregunta","Un framework de Scrum, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sirve como lista de comprobación sistemática para mejorar y reinventar productos o procesos existentes.", noShuffle:false },
  { concept_id:"dig_u4_q37", unit:4, question:"¿Qué es el 'Shadowing' como técnica de investigación etnográfica en innovación?", options:["Hacer sombras con las manos es una accion que no define correctamente este concepto","Acompañar y observar discretamente a un usuario durante su jornada real sin intervenir para comprender sus rutinas y dificultades cotidianas en su entorno natural","Espiar contraseñas, concepto diferente al que se describe en esta pregunta","Un filtro de imagen, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Revela problemas que el usuario ni siquiera menciona en entrevistas porque los tiene asumidos e invisibilizados.", noShuffle:false },
  { concept_id:"dig_u4_q38", unit:4, question:"¿Qué es el concepto 'Servant Leadership' (Liderazgo Servicial) característico del Scrum Master y la agilidad?", options:["Tener sirvientes en la oficina, concepto diferente al que se describe en esta pregunta","Un estilo de liderazgo donde el líder se pone al servicio del equipo para empoderarlo, remover obstáculos, fomentar su crecimiento y autonomía en lugar de imponer órdenes de mando y control jerárquico","Un tipo de contrato de hostelería, concepto diferente al que se describe en esta pregunta","Un organigrama militar, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Fomenta la confianza, la responsabilidad compartida y equipos de alto rendimiento autoorganizados.", noShuffle:false },
  { concept_id:"dig_u4_q39", unit:4, question:"¿Qué es el 'Spike' en la planificación ágil de software?", options:["Una vulnerabilidad de seguridad, concepto diferente al que se describe en esta pregunta","Una tarea de investigación técnica o experimento breve acotado en tiempo (time-boxed) para responder a una duda o reducir la incertidumbre técnica antes de poder estimar una historia compleja","Un pico de tráfico en la web, concepto diferente al que se describe en esta pregunta","Un error fatal en producción, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite investigar librerías o probar arquitecturas antes de comprometerse con estimaciones a ciegas.", noShuffle:false },
  { concept_id:"dig_u4_q40", unit:4, question:"¿Qué diferencia hay entre 'Criterios de Aceptación' y la 'Definition of Done'?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","La Definition of Done es el estándar universal de calidad aplicable a TODAS las historias del proyecto; los Criterios de Aceptación son condiciones de negocio específicas y exclusivas de UNA historia concreta","Los criterios de aceptación los decide el programador, concepto que se aplica en un contexto distinto","La DoD la escribe el cliente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ambos son complementarios y necesarios para considerar que una funcionalidad está verdaderamente terminada.", noShuffle:false },
  { concept_id:"dig_u4_q41", unit:4, question:"¿Qué es la 'Seguridad Psicológica' (Psychological Safety) en equipos innovadores según el Proyecto Aristóteles de Google?", options:["Tener guardias en la puerta, concepto diferente al que se describe en esta pregunta","La creencia compartida por los miembros del equipo de que el grupo es seguro para asumir riesgos interpersonales, hacer preguntas, admitir errores y proponer ideas sin temor al ridículo o castigo","Un software antivirus en los PCs, que aunque es una herramienta util, no corresponde a esta definicion","Un seguro médico privado, que pertenece a un ambito distinto del aqui estudiado"], correct:1, explanation:"Google demostró que la seguridad psicológica es el factor número uno que distingue a los equipos extraordinarios del resto.", noShuffle:false },
  { concept_id:"dig_u4_q42", unit:4, question:"¿Qué es el 'Double Diamond' (Doble Diamante) del Design Council británico?", options:["Un anillo de diamantes costoso, concepto diferente al que se describe en esta pregunta","Un modelo visual del proceso de diseño que describe dos fases sucesivas de divergencia (exploración amplia) y convergencia (foco y definición): Descubrir/Definir (el problema correcto) y Desarrollar/Entregar (la solución correcta)","Un tipo de base de datos en anillo, concepto diferente al que se describe en esta pregunta","Un patrón de arquitectura software, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Garantiza que el equipo dedique suficiente tiempo a entender el problema real antes de precipitarse a programar soluciones erróneas.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 5 — Sostenibilidad, Modelos Digitales y Ética
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dig_u5_q1", unit:5, question:"¿Qué es el 'Green IT' o Computación Verde?", options:["Pintar los servidores de color verde, concepto diferente al que se describe en esta pregunta","El diseño, fabricación, uso y disposición ecológica de ordenadores","Un software para cultivar plantas, que aunque es una herramienta util, no corresponde a esta definicion","Comprar ordenadores ecológicos baratos es una accion que no define correctamente este concepto"], correct:1, explanation:"Abarca desde la eficiencia energética de centros de datos hasta el reciclaje responsable de chatarra electrónica (e-waste).", noShuffle:false },
  { concept_id:"dig_u5_q2", unit:5, question:"¿Qué representa la métrica PUE (Power Usage Effectiveness) en la eficiencia de centros de datos?", options:["El precio de la electricidad, que puede confundirse con este termino en contabilidad general","La relación entre la energía total consumida por todo el centro de datos (incluyendo refrigeración, iluminación y pérdidas) y la energía consumida estrictamente por los equipos de TI (servidores, redes); el valor ideal perfecto es 1.0","La velocidad de procesamiento, concepto que se aplica en un contexto distinto","El número de procesadores verdes, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Cuanto más cercano a 1.0 sea el PUE, menos energía se desperdicia en sistemas auxiliares de refrigeración.", noShuffle:false },
  { concept_id:"dig_u5_q3", unit:5, question:"¿Qué porcentaje aproximado del consumo eléctrico mundial y de las emisiones globales de gases de efecto invernadero (GEI) se atribuye actualmente al sector digital y datacenters?", options:["Menos del 0.01%, concepto diferente al que se describe en esta pregunta","Aproximadamente entre el 2% y el 4% de las emisiones globales de carbono (comparable a toda la aviación comercial mundial) y en rápido crecimiento","Más del 50%, concepto diferente al que se describe en esta pregunta","El 100% de la energía mundial, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La digitalización no es inmaterial: el streaming masivo, la nube y el entrenamiento de modelos de IA demandan ingentes cantidades de electricidad y agua.", noShuffle:false },
  { concept_id:"dig_u5_q4", unit:5, question:"¿Qué es el 'Greenwashing' en el sector tecnológico y empresarial?", options:["Limpiar servidores con agua, concepto diferente al que se describe en esta pregunta","Una práctica deshonesta de marketing donde una empresa se promociona falsamente como ecológica, sostenible o 'cero emisiones' mediante publicidad engañosa sin aplicar cambios reales significativos en su impacto ambiental","Comprar ordenadores con certificación europea es una accion que no define correctamente este concepto","Un tipo de reciclaje de plástico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La Unión Europea está endureciendo la legislación para prohibir afirmaciones medioambientales genéricas y no verificables.", noShuffle:false },
  { concept_id:"dig_u5_q5", unit:5, question:"¿Qué son los 'ODS' (Objetivos de Desarrollo Sostenible) de la Agenda 2030 de la ONU?", options:["Diecisiete lenguajes de programación, concepto diferente al que se describe en esta pregunta","Un conjunto de 17 objetivos globales interconectados adoptados por la ONU para erradicar la pobreza, proteger el planeta y asegurar la paz y prosperidad global para 2030","Diecisiete directivas de la Unión Europea, concepto diferente al que se describe en esta pregunta","Un listado de empresas sostenibles, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La digitalización es un catalizador transversal clave para metas como educación de calidad (ODS 4), industria e innovación (ODS 9) o acción por el clima (ODS 13).", noShuffle:false },
  { concept_id:"dig_u5_q6", unit:5, question:"¿Qué es el 'E-Waste' (Residuos de Aparatos Eléctricos y Electrónicos - RAEE)?", options:["Basura espacial, concepto diferente al que se describe en esta pregunta","Los residuos generados por dispositivos electrónicos desechados (ordenadores, teléfonos, pantallas) que contienen metales pesados altamente contaminantes (plomo, mercurio, cadmio) y minerales escasos valiosos","Los correos eliminados en la papelera, concepto diferente al que se describe en esta pregunta","Los archivos temporales de disco, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es el flujo de residuos de más rápido crecimiento en el mundo, exigiendo circuitos de recogida y reciclaje especializado.", noShuffle:false },
  { concept_id:"dig_u5_q7", unit:5, question:"¿Qué es la 'Obsolescencia Programada' en el diseño de productos tecnológicos?", options:["Un software que actualiza el ordenador, que aunque es una herramienta util, no corresponde a esta definicion","La determinación o planificación deliberada del fin de la vida útil de un dispositivo o software por parte del fabricante para que quede inservible o desfasado tras un tiempo predeterminado forzando a comprar uno nuevo","Un virus informático que caduca, concepto diferente al que se describe en esta pregunta","El final del horario laboral, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Práctica cuestionada éticamente y perseguida por normativas europeas en favor de la durabilidad y reparabilidad.", noShuffle:false },
  { concept_id:"dig_u5_q8", unit:5, question:"¿Qué reconoce el movimiento del 'Derecho a Reparar' (Right to Repair) impulsado por la legislación de la UE?", options:["El derecho a devolver productos en 14 días, concepto diferente al que se describe en esta pregunta","El derecho de consumidores y talleres independientes a tener acceso a piezas de repuesto originales, herramientas diagnósticas, manuales de reparación y actualizaciones de software a precios razonables durante la vida útil del bien","El derecho a tener garantía de 100 años, concepto diferente al que se describe en esta pregunta","El derecho a fabricar ordenadores en casa, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Combate el monopolio de reparación de los fabricantes y prolonga la vida útil de los dispositivos electrónicos reduciendo la chatarra.", noShuffle:false },
  { concept_id:"dig_u5_q9", unit:5, question:"¿Qué es el 'Pasaporte Digital de Producto' (DPP) propuesto en el Pacto Verde Europeo?", options:["Un DNI para personas que viajan con móviles, concepto diferente al que se describe en esta pregunta","Un registro digital accesible que documenta exhaustivamente la procedencia de materiales, huella de carbono, componentes reciclados, reparabilidad y desmontaje de un producto a lo largo de su ciclo de vida","Un visado de compra internacional, concepto diferente al que se describe en esta pregunta","Un certificado de garantía comercial, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Facilita la economía circular permitiendo a recicladores y consumidores conocer la trazabilidad ambiental exacta del bien.", noShuffle:false },
  { concept_id:"dig_u5_q10", unit:5, question:"¿Qué es el 'Sesgo Algorítmico' (Algorithmic Bias) en sistemas de Inteligencia Artificial?", options:["La velocidad de cálculo de un algoritmo, concepto que se aplica en un contexto distinto","Desviaciones sistemáticas e injustas en las predicciones o decisiones de una IA que discriminan a ciertos grupos de personas (por género, raza, edad) debido a datos de entrenamiento históricos sesgados o fallos de diseño","Un error de sintaxis en el código de Python, concepto diferente al que se describe en esta pregunta","Un fallo en la tarjeta gráfica, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si un modelo de contratación se entrena con datos históricos donde no se contrataban mujeres, la IA aprenderá a perpetuar y amplificar esa discriminación.", noShuffle:false },
  { concept_id:"dig_u5_q11", unit:5, question:"¿Qué es el Reglamento Europeo de Inteligencia Artificial (EU AI Act)?", options:["Una ley para crear robots de combate, concepto diferente al que se describe en esta pregunta","El primer marco regulatorio integral del mundo sobre IA que clasifica los sistemas según su nivel de riesgo (Inaceptable, Alto Riesgo, Riesgo Específico/Transparencia y Riesgo Mínimo) imponiendo requisitos de gobernanza estrictos","Una ley que prohíbe el uso de ChatGPT, concepto diferente al que se describe en esta pregunta","Una norma de patentes de software, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Prohíbe sistemas de puntuación social o identificación biométrica masiva en tiempo real y exige auditorías rigurosas para IA de alto riesgo.", noShuffle:false },
  { concept_id:"dig_u5_q12", unit:5, question:"¿Qué es una 'Smart City' (Ciudad Inteligente)?", options:["Una ciudad con muchos universitarios, concepto diferente al que se describe en esta pregunta","Un área urbana que utiliza tecnologías digitales, sensores IoT y Big Data para gestionar de forma eficiente y sostenible sus recursos y servicios: tráfico, transporte público, gestión de residuos, alumbrado y energía","Una ciudad con WiFi gratuito únicamente, concepto diferente al que se describe en esta pregunta","Una ciudad sin coches físicos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Mejora la calidad de vida de los ciudadanos reduciendo costes energéticos y emisiones contaminantes.", noShuffle:false },
  { concept_id:"dig_u5_q13", unit:5, question:"¿Qué es el 'Desarrollo de Software Sostenible' (Green Software Engineering)?", options:["Programar solo con ordenadores reciclados, concepto diferente al que se describe en esta pregunta","Una disciplina que aplica principios de diseño y arquitectura de software para reducir el consumo de energía y las emisiones de carbono del código: algoritmos eficientes, compresión de red, eliminación de código muerto y optimización de consultas","Escribir comentarios en color verde, concepto diferente al que se describe en esta pregunta","Programar al aire libre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un código ineficiente multiplicado por millones de servidores en el mundo equivale a millones de toneladas de CO2 evitables.", noShuffle:false },
  { concept_id:"dig_u5_q14", unit:5, question:"¿Qué son las 'Alcances 1, 2 y 3' (Scopes) en el cálculo de la huella de carbono de una empresa?", options:["Tres tipos de enchufes eléctricos, concepto diferente al que se describe en esta pregunta","Alcance 1: emisiones directas de la empresa (vehículos propios)","Tres niveles de multas ambientales, concepto diferente al que se describe en esta pregunta","Tres categorías de residuos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"En empresas tecnológicas y de software, el Alcance 3 (servicios cloud contratados y dispositivos de clientes) suele concentrar más del 80% de su huella real.", noShuffle:false },
  { concept_id:"dig_u5_q15", unit:5, question:"¿Qué es la 'Explicabilidad de la Inteligencia Artificial' (XAI - Explainable AI)?", options:["Enseñar a programar a los usuarios, concepto diferente al que se describe en esta pregunta","El conjunto de métodos que permiten que los resultados y decisiones tomadas por modelos de aprendizaje automático complejos sean comprensibles, transparentes y auditables para los humanos, superando el problema de la 'caja negra'","Un manual de usuario de la IA, concepto diferente al que se describe en esta pregunta","Un lenguaje de programación claro, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Indispensable en medicina, justicia y banca donde denegar un crédito o un tratamiento exige justificar el motivo exacto.", noShuffle:false },
  { concept_id:"dig_u5_q16", unit:5, question:"¿Qué impacto tiene el entrenamiento de grandes modelos de lenguaje (LLMs) en el consumo de agua dulce de los centros de datos?", options:["Ninguno, los ordenadores no beben agua, concepto diferente al que se describe en esta pregunta","Un impacto severo: los sistemas de refrigeración evaporativa de los supercomputadores consumen millones de litros de agua potable para disipar el calor generado durante el entrenamiento y la inferencia masiva","El agua se utiliza para fabricar chips exclusivamente, concepto diferente al que se describe en esta pregunta","Las nubes de internet usan lluvia, concepto que se aplica en un contexto distinto"], correct:1, explanation:"La huella hídrica de los datacenters es una preocupación medioambiental creciente en zonas con estrés hídrico.", noShuffle:false },
  { concept_id:"dig_u5_q17", unit:5, question:"¿Qué es el 'Efecto Rebote' (Paradoja de Jevons) aplicado a la eficiencia digital?", options:["Un virus informático que rebota entre servidores, concepto diferente al que se describe en esta pregunta","Un fenómeno donde el aumento de la eficiencia energética de una tecnología reduce su coste unitario, lo que provoca un incremento tan masivo de su consumo total que el gasto energético global final es mayor que antes de la mejora","Un fallo en la carga de la batería, concepto diferente al que se describe en esta pregunta","Un error de diseño de software, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Hacer la transmisión de vídeo más eficiente no redujo la energía porque la gente pasó a consumir millones de horas en 4K.", noShuffle:false },
  { concept_id:"dig_u5_q18", unit:5, question:"¿Qué papel juegan los minerales críticos o 'Tierras Raras' (litio, cobalto, neodimio) en la transición digital?", options:["No tienen relación con la tecnología, concepto diferente al que se describe en esta pregunta","Son materias primas indispensables para fabricar baterías de alta capacidad, pantallas, motores eléctricos y chips semiconductores, cuya extracción genera tensiones geopolíticas e impactos ambientales severos","Son piedras decorativas de servidores, concepto diferente al que se describe en esta pregunta","Se usan para fabricar cables de plástico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Plantea el reto del reciclaje circular para no depender de suministros no renovables y cadenas de suministro frágiles.", noShuffle:false },
  { concept_id:"dig_u5_q19", unit:5, question:"¿Qué es el 'Dumping Electrónico' en el comercio internacional de residuos?", options:["Vender ordenadores baratos es una accion que no define correctamente este concepto","La exportación ilegal de residuos electrónicos peligrosos desde países desarrollados hacia países en vías de desarrollo bajo la etiqueta falsa de 'material de segunda mano', creando vertederos tóxicos altamente contaminantes","Un descuento en tiendas de informática, concepto diferente al que se describe en esta pregunta","Un virus de spam, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Convenios como el de Basilea intentan frenar este tráfico que intoxica comunidades vulnerables en África y Asia.", noShuffle:false },
  { concept_id:"dig_u5_q20", unit:5, question:"¿Qué es la 'Economía de la Atención' (Attention Economy) y qué dilemas éticos plantea en el diseño digital?", options:["Cobrar por cada minuto de atención al cliente es una accion que no define correctamente este concepto","Un modelo donde el recurso escaso y monetizable es el tiempo y atención humana, incentivando a plataformas a diseñar interfaces adictivas con notificaciones intrusivas y algoritmos que polarizan para retener a los usuarios","Vender cursos de concentración es una accion que no define correctamente este concepto","Un tipo de publicidad en vallas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Diseñadores éticos promueven el 'Time Well Spent' y el 'Humane Tech' para proteger la salud mental de los usuarios.", noShuffle:false },
  { concept_id:"dig_u5_q21", unit:5, question:"¿Qué es un 'Algoritmo de Caja Negra' (Black Box Model)?", options:["Un ordenador pintado de negro, concepto diferente al que se describe en esta pregunta","Un modelo de IA (como redes neuronales profundas) cuya lógica interna y pesos matemáticos son tan intrincados y masivos que resulta imposible para un ser humano desentrañar exactamente cómo llegó a una conclusión específica","Un virus oculto, concepto diferente al que se describe en esta pregunta","Una base de datos encriptada, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Plantea graves dilemas jurídicos y éticos cuando se utiliza para dictar sentencias judiciales o evaluar solvencia financiera.", noShuffle:false },
  { concept_id:"dig_u5_q22", unit:5, question:"¿Qué son los 'Principios Éticos para una IA Confiable' formulados por la Comisión Europea?", options:["Diez mandamientos religiosos, concepto diferente al que se describe en esta pregunta","Directrices que exigen que la IA sea: lícita (cumplir la ley)","Un manual de programación en C++, concepto diferente al que se describe en esta pregunta","Un conjunto de patentes de software, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La Unión Europea lidera el marco global para garantizar que la tecnología esté al servicio del ser humano y no al revés.", noShuffle:false },
  { concept_id:"dig_u5_q23", unit:5, question:"¿Qué es la 'Pobreza Energética Digital'?", options:["No tener dinero para pagar la luz del ordenador, concepto diferente al que se describe en esta pregunta","La situación de hogares que carecen de los recursos económicos o equipamiento tecnológico eficiente necesario para acceder a servicios digitales básicos (educación telemática, teletrabajo, trámites públicos) de forma continuada","Un corte de luz temporal, concepto diferente al que se describe en esta pregunta","Una factura cara de teléfono, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Agrava la exclusión social en un mundo donde realizar cualquier trámite oficial exige conectividad y ordenador.", noShuffle:false },
  { concept_id:"dig_u5_q24", unit:5, question:"¿Qué es la 'Desconexión Digital' reconocida como derecho laboral en el artículo 88 de la LOPDGDD?", options:["Apagar los servidores de la empresa el fin de semana, concepto diferente al que se describe en esta pregunta","El derecho de los trabajadores a no responder correos, mensajes o llamadas corporativas fuera de su horario laboral establecido para garantizar su tiempo de descanso, permisos y salud mental","Prohibir el teletrabajo, concepto diferente al que se describe en esta pregunta","Desconectar el cable de internet en la oficina, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Protege la conciliación de la vida personal y laboral frente a la cultura de hiperdisponibilidad permanente que fomentan los teléfonos móviles.", noShuffle:false },
  { concept_id:"dig_u5_q25", unit:5, question:"¿Qué es un 'Contrato Inteligente Sostenible' en cadenas de suministro agroalimentarias?", options:["Un papel ecológico reciclado, concepto diferente al que se describe en esta pregunta","Un smart contract en blockchain que verifica automáticamente certificaciones ecológicas y de comercio justo antes de autorizar el pago a agricultores, garantizando la trazabilidad verde directa al consumidor","Un contrato de energía solar, que pertenece a un ambito distinto del aqui estudiado","Una ley agrícola, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite al consumidor escanear un código en el supermercado y conocer toda la huella de transporte y autenticidad del producto.", noShuffle:false },
  { concept_id:"dig_u5_q26", unit:5, question:"¿Qué es el 'Ecodiseño' (Ecodesign) aplicado a productos digitales y dispositivos electrónicos?", options:["Poner fotos de árboles en la carcasa, concepto diferente al que se describe en esta pregunta","La integración sistemática de aspectos medioambientales en el diseño del producto desde su fase inicial","Hacer ordenadores de madera es una accion que no define correctamente este concepto","Vender sin embalaje es una accion que no define correctamente este concepto"], correct:1, explanation:"El 80% del impacto ambiental de un producto se determina durante su fase de diseño inicial.", noShuffle:false },
  { concept_id:"dig_u5_q27", unit:5, question:"¿Qué beneficio medioambiental aporta la adopción universal del conector USB Tipo-C impuesta por la Unión Europea para dispositivos electrónicos?", options:["Que los teléfonos cargan más lento, concepto diferente al que se describe en esta pregunta","La reducción drástica de residuos electrónicos (e-waste) al permitir a los consumidores reutilizar un único cargador y cable para teléfonos, tablets, cámaras y portátiles, evitando la proliferación de cargadores incompatibles","Aumentar las ventas de adaptadores, concepto diferente al que se describe en esta pregunta","Es una directiva puramente estética, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ahorra miles de toneladas de residuos al año y millones de euros a los ciudadanos europeos.", noShuffle:false },
  { concept_id:"dig_u5_q28", unit:5, question:"¿Qué es el 'Carbon Offsetting' (Compensación de Carbono) y por qué debe ser la última opción tras la reducción?", options:["Comprar carbón barato es una accion que no define correctamente este concepto","Financiar proyectos ambientales externos para compensar las emisiones que una empresa no ha podido eliminar; es la última opción porque primero se debe evitar y reducir la emisión real en origen","Un impuesto sobre el carbón mineral, que pertenece a un ambito distinto del aqui estudiado","Un tipo de energía renovable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La compensación sin reducción previa es a menudo criticada como una forma de greenwashing que no ataja la causa raíz de las emisiones.", noShuffle:false },
  { concept_id:"dig_u5_q29", unit:5, question:"¿Qué es la 'Reutilización y Remanufactura' (Refurbished / Reacondicionado) en hardware digital?", options:["Tirar el ordenador viejo a la basura, concepto diferente al que se describe en esta pregunta","El proceso industrial de revisar, reparar, limpiar y actualizar dispositivos electrónicos usados garantizando su perfecto funcionamiento para reintroducirlos en el mercado con garantía a menor precio","Comprar productos piratas es una accion que no define correctamente este concepto","Vender componentes rotos es una accion que no define correctamente este concepto"], correct:1, explanation:"Alarga la vida útil de los equipos evitando la emisión de carbono que supone fabricar un dispositivo nuevo desde cero.", noShuffle:false },
  { concept_id:"dig_u5_q30", unit:5, question:"¿Qué es el 'Free and Open Source Software' (FOSS / Código Abierto) como habilitador de sostenibilidad digital?", options:["Software que no cuesta dinero pero no se puede ver el código","Software cuyo código fuente es libremente accesible, auditable y modificable","Un software de prueba que dura 30 días, que aunque es una herramienta util, no corresponde a esta definicion","Un programa de piratería, que aunque es una herramienta util, no corresponde a esta definicion"], correct:1, explanation:"Sistemas como Linux permiten reutilizar ordenadores de hace 15 años como terminales productivos perfectamente seguros y funcionales.", noShuffle:false },
  { concept_id:"dig_u5_q31", unit:5, question:"¿Qué es la 'Huella Digital de un Usuario' (Digital Footprint)?", options:["La huella dactilar para desbloquear el móvil, concepto diferente al que se describe en esta pregunta","El rastro de datos personales, historial de navegación, compras","La marca de los dedos en la pantalla, concepto que se aplica en un contexto distinto","Un medidor de pasos diarios, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Configura la reputación online del usuario y se utiliza por empresas de publicidad y reclutamiento para perfilar su conducta.", noShuffle:false },
  { concept_id:"dig_u5_q32", unit:5, question:"¿Qué son los 'Dark Patterns' desde una perspectiva ética y legal?", options:["Páginas web con fondo negro, concepto diferente al que se describe en esta pregunta","Mecanismos de diseño engañosos que manipulan las debilidades cognitivas de los usuarios para forzar decisiones en contra de su propio interés","Interfaces para personas ciegas, concepto diferente al que se describe en esta pregunta","Fallos de renderizado de CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Vulneran la autonomía de las personas y están expresamente perseguidos por normativas de protección del consumidor de la UE.", noShuffle:false },
  { concept_id:"dig_u5_q33", unit:5, question:"¿Qué es la 'Teoría de las Tres R' aplicada al consumo digital?", options:["Rápido, Rentable y Robusto, concepto diferente al que se describe en esta pregunta","Reducir (el consumo superfluo de dispositivos y datos), Reutilizar (aparatos y componentes) y Reciclar (adecuadamente la chatarra electrónica)","Redes, Rutas y Routers, concepto diferente al que se describe en esta pregunta","Ransomware, Redundancia y Registro, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La jerarquía de residuos prioriza siempre evitar generar el residuo antes que tener que gestionarlo.", noShuffle:false },
  { concept_id:"dig_u5_q34", unit:5, question:"¿Qué impacto tiene la computación en la nube alimentada por energías 100% renovables en los proveedores cloud?", options:["Que los servidores funcionan solo de día, concepto diferente al que se describe en esta pregunta","La firma de contratos de compraventa de energía limpia a largo plazo (PPA - Power Purchase Agreements) con parques solares y eólicos para descarbonizar el consumo masivo de sus centros de datos","Que los ordenadores son más lentos, concepto diferente al que se describe en esta pregunta","Ninguno, es solo publicidad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Compañías como Google, Microsoft y AWS se han convertido en los mayores compradores corporativos de energía renovable del planeta.", noShuffle:false },
  { concept_id:"dig_u5_q35", unit:5, question:"¿Qué es la 'Gobernanza de Datos Ética' en una empresa digital?", options:["El control exclusivo por parte de los accionistas, concepto diferente al que se describe en esta pregunta","El conjunto de políticas organizativas que aseguran que los datos se recopilan y usan con integridad, transparencia, respeto irrestricto a la privacidad y sin perjudicar a los colectivos vulnerables","Vender bases de datos al mejor postor es una accion que no define correctamente este concepto","Ocultar la información contable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Va más allá del cumplimiento legal estricto: se pregunta no solo '¿Podemos hacer esto legalmente?' sino '¿Es correcto y ético hacerlo?'.", noShuffle:false },
  { concept_id:"dig_u5_q36", unit:5, question:"¿Qué es la 'Tecnofobia' frente a la 'Tecnofilia' en la sociedad?", options:["El amor por los teléfonos móviles, concepto diferente al que se describe en esta pregunta","La tecnofobia es el miedo o rechazo irracional hacia la tecnología y la automatización; la tecnofilia es la fascinación y dependencia ciega de la tecnología considerándola la solución mágica a todos los problemas","Son dos marcas comerciales, concepto diferente al que se describe en esta pregunta","Dos tipos de cables de red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La educación digital debe fomentar un espíritu crítico equilibrado que aproveche la tecnología sin caer en el fanatismo ni en el pánico.", noShuffle:false },
  { concept_id:"dig_u5_q37", unit:5, question:"¿Qué papel juegan las 'Baterías de Estado Sólido' en la sostenibilidad del hardware digital futuro?", options:["No usan electricidad, concepto diferente al que se describe en esta pregunta","Sustituyen los electrolitos líquidos inflamables de las baterías de litio tradicionales por materiales sólidos cerámicos, ofreciendo el doble de densidad energética, cargas ultrarrápidas y mayor vida útil sin riesgo de incendio","Son baterías hechas de piedra, concepto diferente al que se describe en esta pregunta","Son baterías que no se recargan, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Prometen duplicar la autonomía de dispositivos y vehículos eléctricos reduciendo el impacto ambiental de reemplazo.", noShuffle:false },
  { concept_id:"dig_u5_q38", unit:5, question:"¿Qué es la 'Neutralidad de la Red' (Net Neutrality)?", options:["Que todos los cables sean de color blanco, concepto diferente al que se describe en esta pregunta","El principio fundamental de que los proveedores de internet (ISPs) deben tratar todo el tráfico de datos por igual, sin bloquear, ralentizar ni cobrar tarifas preferenciales según el contenido, aplicación o sitio web","Tener internet gratuito en todos los países, concepto diferente al que se describe en esta pregunta","Que no haya servidores en la red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Protege la libre competencia y la libertad de expresión impidiendo que grandes corporaciones paguen a las telecos para aplastar a startups rivales.", noShuffle:false },
  { concept_id:"dig_u5_q39", unit:5, question:"¿Qué es el 'Efecto Burbuja de Filtro' (Filter Bubble) en redes sociales?", options:["Un filtro fotográfico para la cara, concepto diferente al que se describe en esta pregunta","El aislamiento intelectual de un usuario en su propia burbuja de información personalizada donde los algoritmos solo le recomiendan contenidos afines a sus ideas previas, eliminando visiones opuestas y polarizando a la sociedad","Un error de conexión de red, concepto diferente al que se describe en esta pregunta","Un tipo de pantalla de privacidad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Plantea graves riesgos para la democracia y el debate cívico al alimentar cámaras de eco de desinformación.", noShuffle:false },
  { concept_id:"dig_u5_q40", unit:5, question:"¿Qué es un 'Data Center Sumergido' (como el Proyecto Natick de Microsoft)?", options:["Un centro de datos inundado por accidente, concepto diferente al que se describe en esta pregunta","Hundir contenedores sellados de servidores en el fondo del mar para aprovechar la refrigeración pasiva gratuita del agua fría del océano y reducir drásticamente el consumo eléctrico y las tasas de fallo","Un submarino militar con ordenadores, concepto diferente al que se describe en esta pregunta","Un parque acuático digital, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Demostró una tasa de fallos de hardware 8 veces menor que en tierra al no haber oxígeno ni humedad variable y un PUE extremadamente bajo.", noShuffle:false },
  { concept_id:"dig_u5_q41", unit:5, question:"¿Qué es el 'Human-in-the-Loop' (Humano en el Bucle) en la toma de decisiones con IA?", options:["Un programador atado a un servidor, concepto diferente al que se describe en esta pregunta","Un diseño de sistema donde las decisiones críticas tomadas por la inteligencia artificial (ej","Un bucle infinito de código, concepto diferente al que se describe en esta pregunta","Una reunión de directivos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Exigido por la legislación europea para garantizar que las máquinas asistan pero no sustituyan la responsabilidad moral humana.", noShuffle:false },
  { concept_id:"dig_u5_q42", unit:5, question:"¿Por qué la digitalización sostenible se considera una 'Transición Gemela' (Twin Transition) junto con la transición ecológica?", options:["Porque son dos ordenadores gemelos, concepto diferente al que se describe en esta pregunta","Porque la Unión Europea establece que la transformación digital y la transición ecológica deben ir indisolublemente de la mano: la tecnología digital debe ser el habilitador clave para descarbonizar la economía sin convertirse ella misma en un problema ambiental","Porque nacieron el mismo año, concepto diferente al que se describe en esta pregunta","Porque usan dos cables, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"No puede haber una transición verde sin sensores y gemelos digitales que optimicen la energía, ni una digitalización válida si arrasa el planeta con emisiones y residuos.", noShuffle:false }
];
